  '\\nNPS Table Matrix\\n' => 'Matrice de table NPS',
  '\\nJalali Date\\n' => 'Date Jalali',
  '\\nHijri Date\\n' => 'Date de l\'Hégire',
  '\\nInstall the add-on\\n' => 'Installer le module complémentaire',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons\\n' => 'Veuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Jalili',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons\\n' => 'Veuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Hijri',
  'warning' => 'avertissement',
  '\\ndate & time\\n' => 'date et heure',
  '\\nEnable file upload in the response box\\n' => 'Activer le téléchargement de fichiers dans la zone de réponse',
  '\\nEnable Google reCAPTCHA in the response box\\n' => 'Activez Google reCAPTCHA dans la zone de réponse',
  '\\nEnable download button in the response box\\n' => 'Activer le bouton de téléchargement dans la zone de réponse',
  '\\nDisplay the IP addresses of users in the response box.\\n' => 'Affichez les adresses IP des utilisateurs dans la zone de réponse.',
  '\\nPersia Payment Add-on\\n' => 'Module complémentaire de paiement Persia',
  '\\nThe Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.\\n' => 'Le module complémentaire de paiement Persia pour Flux Forms vous permet de connecter votre site Web à Persia Payment pour traiter les paiements, les dons et les commandes en ligne.',
  '\\nJalali Date Add-on\\n' => 'Module complémentaire de date Jalali',
  '\\nThe Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.\\n' => 'Le module complémentaire Jalali Date vous permet d\'ajouter un champ de date Jalali à vos formulaires et de créer tout type de formulaire incluant ce champ de date Shamsi.',
  '\\nHijri Date Add-on\\n' => 'Module complémentaire Date Hijri',
  '\\nThe Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.\\n' => 'Le module complémentaire Hijri Date vous permet d\'ajouter un champ de date Hijri à vos formulaires et de créer tout type de formulaire incluant ce champ.',
  '\\nSMS service Add-on\\n' => 'Module complémentaire de service SMS',
  '\\nThe SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.\\n' => 'Le module complémentaire du service SMS vous permet de recevoir des messages SMS de notification lorsque vous ou vos clients recevez de nouveaux messages ou réponses.',
  '\\nPlease install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.\\n' => 'Veuillez installer le module complémentaire de date Hijri ou Jalali. Vous ne pouvez pas installer les deux modules complémentaires simultanément.',
  '\\nResponse box\\n' => 'Boîte de réponse',
  '\\nRegions Drop-Down\\n' => 'liste déroulante des régions',
  '\\nYou are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.\\n' => 'Vous voyez ce message car les modules complémentaires requis sont en cours d\'installation. Veuillez patienter quelques minutes, puis visiter à nouveau cette page. Si plus de cinq minutes se sont écoulées et que rien ne s\'est produit, veuillez contacter l\'équipe d\'assistance de Flux Forms sur Whitestudio.team.',
  '\\nThe cell phone number is incorrect\\n' => 'Le numéro de téléphone portable est incorrect',
  '\\nInvalid country code\\n' => 'Code pays invalide',
  '\\nThe cell phone number is too short\\n' => 'Le numéro de téléphone portable est trop court',
  '\\nThe cell phone number is too long\\n' => 'Le numéro de téléphone portable est trop long',
  '\\nPlease select the number of countries to display within an acceptable range.\\n' => 'Veuillez sélectionner le nombre de pays à afficher dans une plage acceptable.',
  '\\nDisabled Field\\n' => 'Champ désactivé',
  '\\nHidden Field\\n' => 'Champ caché',
  '[[\'Select a country to display a list of states/provinces.\\n' => 'Sélectionnez un pays pour afficher une liste d\'états/provinces.',
  '\\nSelect a state/province to display a list of cities.\\n' => 'Sélectionnez un état/une province pour afficher une liste de villes.',
  '\\nSMS Service Add-on\\n' => 'Module complémentaire de service SMS',
  '[["This field is currently unavailable. Please contact the site administrator.\\n' => 'Ce champ est actuellement indisponible. Veuillez contacter l\'administrateur du site.',
  '\\nWould you like to customize the form using the colors of the active template?\\n' => 'Voulez-vous personnaliser le formulaire en utilisant les couleurs du modèle actif ?',
  '\\nFlux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.\', \'en\']]' => 'Flux Forms a utilisé les couleurs du modèle actif. Veuillez choisir une couleur pour chaque option ci-dessous afin de personnaliser le formulaire que vous créez en fonction des couleurs de votre modèle. En sélectionnant une couleur pour chaque option ci-dessous, la couleur de tous les champs de formulaire associés à cette fonctionnalité changera en conséquence.',
  '\\nButtons text colors\\n' => 'Couleurs du texte des boutons',
  '\\nattached files\\n' => 'fichiers joints',
  '\\nDefault selected\\n' => 'Sélectionné par défaut',
  '\\nShow attributes\\n' => 'Afficher les attributs',
  '\\nHide attributes\\n' => 'Masquer les attributs',
  '\\nThe ID length should be at least 3 characters long.\\n' => 'La longueur de l\'ID doit comporter au moins 3 caractères.',
  '\\nThe ID value must be unique, as it is already being used in this field. Please try a new, unique value.\\n' => 'La valeur de l\'ID doit être unique, car elle est déjà utilisée dans ce champ. Veuillez essayer une nouvelle valeur unique.',
  '\\nImage picker\\n' => 'Sélecteur d\'images',
  '\\nInsert an image url\\n' => 'Insérer une URL d\'image',
  '\\nNew Booking Form\\n' => 'Nouveau formulaire de réservation',
  '\\nConditional Logic Add-on\\n' => 'Module complémentaire de logique conditionnelle',
  '\\nConditional logic Add-on\\n' => 'Module complémentaire de logique conditionnelle',
  '\\nThe Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.\\n' => 'Le module complémentaire Conditional Logic permet d\'activer des formulaires dynamiques et interactifs basés sur des entrées utilisateur spécifiques ou des règles conditionnelles. Il permet de créer des formulaires hautement personnalisés adaptés pour répondre aux besoins uniques des utilisateurs.',
  '\\nThe Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.\\n' => 'Le module de logique conditionnelle n\'a pas pu être chargé. Veuillez actualiser la page ; si le problème persiste, désactivez et réactivez le module complémentaire Conditional Logic.',
  '\\nStop after this rule matches\\n' => 'Arrêtez après que cette règle corresponde',
