  'Documentation' => 'Documentation',
  '\\nClick on the Settings button on the panel page of Flux Forms Plugin and configure the SMS sending method. Then, try again.\\n' => 'Cliquez sur le bouton Paramètres sur la page du panneau du plugin Flux Forms et configurez la méthode d\'envoi de SMS. Ensuite, réessayez.',
