  '\\nPayPal Payment Add-on\\n' => 'Module complémentaire de paiement PayPal',
  '\\nThe PayPal add-on for Flux Forms enables you to integrate your WordPress site with PayPal for payment processing, donations, and online orders.\\n' => 'Le module complémentaire PayPal pour Flux Forms vous permet d\'intégrer votre site WordPress à PayPal pour le traitement des paiements, les dons et les commandes en ligne.',
  '\\nAcceptable file types\\n' => 'Types de fichiers acceptables',
