  '\\nPermission to access your microphone/camera/screen was denied.\\n' => 'L\'autorisation d\'accéder à votre microphone/caméra/écran a été refusée.',
  '\\nYour browser does not support this recording feature.\\n' => 'Votre navigateur ne prend pas en charge cette fonctionnalité d\'enregistrement.',
  '\\nMaximum recording duration reached.\\n' => 'Durée maximale d\'enregistrement atteinte.',
  '\\nMade by Flux Forms\\n' => 'Fabriqué par Flux Forms',
  '\\nTap to start recording\\n' => 'Appuyez pour démarrer l\'enregistrement',
  '\\nDownload recording\\n' => 'Télécharger l\'enregistrement',
  '\\nRecording requires a secure (HTTPS) connection. Please ask the site administrator to enable HTTPS on this host.\\n' => 'L\'enregistrement nécessite une connexion sécurisée (HTTPS). Veuillez demander à l\'administrateur du site d\'activer HTTPS sur cet hôte.',
  '\\nScreen recording is not supported on this device or browser (most mobile browsers do not allow it). Please open the form in a desktop browser such as Chrome, Edge or Firefox.\\n' => 'L\'enregistrement d\'écran n\'est pas pris en charge sur cet appareil ou ce navigateur (la plupart des navigateurs mobiles ne le permettent pas). Veuillez ouvrir le formulaire dans un navigateur de bureau tel que Chrome, Edge ou Firefox.',
  '\\nCountdown before recording\\n' => 'Compte à rebours avant l\'enregistrement',
