  '\\nSearch Fields (Trigger Fields)\\n' => 'Champs de recherche (champs de déclenchement)',
  '\\nPlease select a form first\\n' => 'Veuillez d\'abord sélectionner un formulaire',
  '\\nTarget Fields (Fields to Fill)\\n' => 'Champs cibles (champs à remplir)',
  '\\nMap API response fields to form fields. The API data will automatically fill these fields.\\n' => 'Mappez les champs de réponse de l\'API aux champs de formulaire. Les données de l\'API rempliront automatiquement ces champs.',
  '\\nNo fillable fields found in this form\\n' => 'Aucun champ à remplir trouvé dans ce formulaire',
  '[[\'field\', \'en\']]' . chr(0) . '[[\'fields\', \'en\']]' => 'field' . chr(0) . 'fields',
