  'CSV' => 'CSV',
  '\\nDataset\\n' => 'Ensemble de données',
  '[[\'The%shas been successfully completed\\n' => 'Le%sa été terminé avec succès',
  'Rename' => 'Renommer',
  'Source' => 'Source',
  '\\n%snot found\\n' => '%sintrouvable',
