  '[[\'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.\\n' => 'Flux Donate est actif mais n\'a pas pris en charge les paiements (le filtre flxb_own_payments est désactivé ?). Flux Forms utilise ses propres paramètres Stripe.',
  '\\nFlux Donate is not active; Flux Forms takes payments itself with%s.\\n' => 'Flux Donate n’est pas actif ; Flux Forms accepte lui-même les paiements avec%s.',
  '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\', \'en\']]' . chr(0) . '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".\', \'en\']]' => 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : le formulaire de paiement %daffiche "Le paiement en ligne n\'est pas disponible".' . chr(0) . 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : les formulaires de paiement %dindiquent "Le paiement en ligne n\'est pas disponible".',
  '\\nFlux Donate is not active and no Stripe keys are set. No payment form exists, so nothing is affected.\\n' => 'Flux Donate n\'est pas actif et aucune clé Stripe n\'est définie. Aucun formulaire de paiement n\'existe, rien n\'est donc affecté.',
  '\\nPanel › Settings › Payment\\n' => 'Panneau › Paramètres › Paiement',
