  '\\nVersion%1$sis active; certificate automations need%2$sor later.\\n' => 'La version%1$sest active ; les automatisations de certificats nécessitent%2$sou une version ultérieure.',
  '[[\'Not active, but%dactive automation creates or sends certificates; it will fail.\', \'en\']]' . chr(0) . '[[\'Not active, but%dactive automations create or send certificates; they will fail.\', \'en\']]' => 'Non actif, mais l\'automatisation active%dcrée ou envoie des certificats ; ça va échouer.' . chr(0) . 'Non actif, mais les automatisations actives%dcréent ou envoient des certificats ; ils échoueront.',
  '\\nNot active. Needed only for certificate automations.\\n' => 'Non actif. Nécessaire uniquement pour les automatisations de certificats.',
  '\\nAutomations\\n' => 'Automatisations',
  '\\nNo automation is on. After a form or payment nothing runs automatically (certificate, e-mail, webhook).\\n' => 'Aucune automatisation n\'est activée. Après un formulaire ou un paiement, rien ne s\'exécute automatiquement (certificat, e-mail, webhook).',
  '[[\'%dautomation is on.\', \'en\']]' . chr(0) . '[[\'%dautomations are on.\', \'en\']]' => ' L\'automatisation %dest activée.' . chr(0) . ' Les automatisations %dsont activées.',
  '[[\'%drun failed in the last 7 days; see the run log.\', \'en\']]' . chr(0) . '[[\'%druns failed in the last 7 days; see the run log.\', \'en\']]' => ' L\'exécution de %da échoué au cours des 7 derniers jours ; voir le journal d\'exécution.' . chr(0) . ' Les exécutions %dont échoué au cours des 7 derniers jours ; voir le journal d\'exécution.',
  '\\nKeys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.\\n' => 'Les clés sont définies ; Le formulaire %dutilise reCAPTCHA. Les formulaires %dutilisent reCAPTCHA.',
