  '\\nDatasets\\n' => 'Ensembles de données',
  '\\nDatasets available for auto-populate\\n' => 'Ensembles de données disponibles pour le remplissage automatique',
  '\\nNo datasets yet. Upload a CSV file to get started.\\n' => 'Aucun ensemble de données pour l\'instant. Téléchargez un fichier CSV pour commencer.',
  '\\nHow to use Auto-Populate Datasets\\n' => 'Comment utiliser les ensembles de données à remplissage automatique',
  '\\nPrepare a CSV file with column headers in the first row.\\n' => 'Préparez un fichier CSV avec des en-têtes de colonnes dans la première ligne.',
  '[[\'Prepare CSV\\n' => 'Préparer le CSV',
  '\\nUpload the CSV file using the upload button.\\n' => 'Téléchargez le fichier CSV à l\'aide du bouton de téléchargement.',
  '\\nUpload Dataset\\n' => 'Télécharger l\'ensemble de données',
  '\\nIn Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.\', \'en\']]' => 'Dans Form Builder, ouvrez les paramètres du formulaire et activez « Remplir automatiquement ». Choisissez votre ensemble de données, puis mappez les éléments aux champs de l\'ensemble de données comme conditions de recherche.',
  '\\nEnable Auto-Populate\\n' => 'Activer le remplissage automatique',
  '[[\'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.\\n' => 'Pour chaque champ cible, activez « Remplir automatiquement ce champ » et sélectionnez la colonne de l\'ensemble de données à remplir automatiquement.',
  '\\nMap Fields\\n' => 'Champs de carte',
  '\\nYou can edit dataset values inline by clicking on them.\\n' => 'Vous pouvez modifier les valeurs de l\'ensemble de données en ligne en cliquant dessus.',
  '\\nFollow these steps to set up auto-populate for your forms\\n' => 'Suivez ces étapes pour configurer le remplissage automatique de vos formulaires',
  '\\nQuick Start Guide\\n' => 'Guide de démarrage rapide',
  '\\nTips & Notes\\n' => 'Conseils et remarques',
  '\\nEditing Data\\n' => 'Modification des données',
  '\\nSupported format: CSV with UTF-8 encoding.\\n' => 'Format pris en charge : CSV avec encodage UTF-8.',
  '\\nForm Builder Tips\\n' => 'Conseils pour le générateur de formulaires',
  '[[\'Use conditions to filter dataset rows based on user input.\\n' => 'Utiliser des conditions pour filtrer les lignes de l\'ensemble de données en fonction des entrées de l\'utilisateur.',
  '\\nMultiple fields can auto-populate from the same dataset.\\n' => 'Plusieurs champs peuvent être renseignés automatiquement à partir du même ensemble de données.',
  'Good to know' => 'Bon à savoir',
  '\\nChanges to the dataset take effect immediately for new form submissions.\\n' => 'Les modifications apportées à l\'ensemble de données prennent effet immédiatement pour les nouvelles soumissions de formulaire.',
  '\\nConnect & Manage API Integrations\\n' => 'Connectez-vous et gérez les intégrations d\'API',
