  '\\nSubscription ID\\n' => 'ID d\'abonnement',
  '\\nPlan ID\\n' => 'ID du plan',
  '\\nCapture ID\\n' => 'Capturer l\'ID',
  '\\nPayment Type\\n' => 'Type de paiement',
  '\\nPayer Email\\n' => 'E-mail du payeur',
  '\\nPayer Name\\n' => 'Nom du payeur',
  '\\nTracking Code\\n' => 'Code de suivi',
  '\\nPayment Details\\n' => 'Détails du paiement',
  '\\nSubscription Details\\n' => 'Détails de l\'abonnement',
  '\\nof\\n' => 'de',
  '\\nRows per page\\n' => 'Lignes par page',
  '\\nSuspended\\n' => 'Suspendu',
  '\\nSubscription suspended successfully.\\n' => 'Abonnement suspendu avec succès.',
  '\\nSubscription reactivated successfully.\\n' => 'L\'abonnement a été réactivé avec succès.',
  '\\nPayment Management Dashboard\\n' => 'Tableau de bord de gestion des paiements',
  '\\nManage and track all%stransactions. View payment details, process refunds, and export records.\\n' => 'Gérez et suivez toutes les transactions%s. Afficher les détails du paiement, traiter les remboursements et exporter les enregistrements.',
  '\\nSecure\\n' => 'Sécurisé',
  '\\nDownload payment records\\n' => 'Télécharger les enregistrements de paiement',
  'Start' => 'Commencer',
  '\\nLast Payment\\n' => 'Dernier paiement',
  '\\nPowered by\\n' => 'Propulsé par',
  '\\nand Bootstrap Icon. Created by\', \'en\']]' => 'et Icône d\'amorçage. Créé par',
  '\\nGoogle Sheet\\n' => 'Feuille Google',
  '\\nSync Form Responses to Google Sheets\\n' => 'Synchroniser les réponses du formulaire avec Google Sheets',
  '\\nAutomatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.\\n' => 'Envoyez automatiquement les soumissions de formulaires à vos feuilles de calcul Google. Connectez un ou plusieurs comptes de service, associez une feuille à chaque formulaire et laissez les données circuler en temps réel : aucun webhook ou connexion au navigateur n\'est requis.',
  'Connected' => 'Connecté',
  '\\nNot Connected\\n' => 'Non connecté',
  '\\nAuto Sync\\n' => 'Synchronisation automatique',
  '\\nAuto Header\\n' => 'En-tête automatique',
  '\\nSync Logs\\n' => 'Journaux de synchronisation',
  '\\nGoogle Sheet Settings\\n' => 'Paramètres de feuille Google',
  '\\nActive Bindings\\n' => 'Liaisons actives',
  '[[\'Form\', \'en\']]' . chr(0) . '[[\'Forms\', \'en\']]' => 'Formulaire' . chr(0) . 'Formulaires',
  '[[\'%dservice account connected\', \'en\']]' . chr(0) . '[[\'%dservice accounts connected\', \'en\']]' => 'Compte de service %dconnecté' . chr(0) . ' Comptes de service %dconnectés',
  '\\nNo service account connected yet\\n' => 'Aucun compte de service n\'est encore connecté',
  '\\nForm Bindings\\n' => 'Liaisons de formulaire',
  '\\nHelp & Guide\\n' => 'Aide et guide',
  'Something went wrong.' => 'Quelque chose s\'est mal passé.',
  '\\nSaved successfully.\\n' => 'Enregistré avec succès.',
  'Remove' => 'Supprimer',
  '\\nOpen in Google Sheets\\n' => 'Ouvrir dans Google Sheets',
  '\\nService Accounts\\n' => 'Comptes de service',
  '\\nConnect one or more Google service accounts — no browser login required\\n' => 'Connectez un ou plusieurs comptes de service Google – aucune connexion au navigateur requise',
  '\\nYour server is missing the PHP OpenSSL extension.\\n' => 'Votre serveur ne dispose pas de l\'extension PHP OpenSSL.',
  '\\nGoogle Sheet sync cannot work until it is enabled. Please ask your host to enable the%sPHP extension, then reload this page.\\n' => 'La synchronisation de Google Sheet ne peut pas fonctionner tant qu\'elle n\'est pas activée. Veuillez demander à votre hébergeur d\'activer l\'extension PHP%s, puis recharger cette page.',
  'Not tested' => 'Non testé',
  '\\nCopy this email\\n' => 'Copiez cet e-mail',
  '\\nCopy email\\n' => 'Copier l\'e-mail',
  '\\nTo sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.\\n' => 'Pour synchroniser une feuille<strong></strong>existante : ouvrez-la dans Google Sheets →<strong>Partager</strong>→ collez l\'e-mail ci-dessus → définissez le rôle sur<strong>Editeur</strong>. Pour créer une nouvelle feuille<strong></strong>, utilisez simplement les liaisons de formulaire : aucun partage n\'est nécessaire.',
  '\\nSet Default\\n' => 'Définir par défaut',
  '\\nRetest\\n' => 'Retester',
  '\\nLet’s connect Google Sheets — about 3 minutes, one time\', \'en\']]' => 'Connectons Google Sheets — environ 3 minutes, une fois',
  '\\nFollow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.\\n' => 'Suivez les étapes numérotées à droite pour télécharger une clé de compte de service gratuite auprès de Google, puis déposez le fichier ci-dessous. Vous ne faites cela qu\'une seule fois. Après cela, créer une feuille pour n\'importe quel formulaire se fait en quelques clics.',
  '\\nYour Google email\\n' => 'Votre adresse e-mail Google',
  '\\n(recommended)\\n' => '(recommandé)',
  '\\nAny sheet the plugin<strong>creates</strong>is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.\\n' => 'Toute feuille créée par le plug-in<strong></strong>est automatiquement partagée avec cette adresse. Elle apparaît donc dans votre propre Google Drive sous "Partagé avec moi". Sans cela, les nouvelles feuilles restent cachées dans le compte de service.',
  '\\nEnable Google Sheet Integration\\n' => 'Activer l\'intégration de Google Sheet',
  '\\nSync form submissions to your spreadsheets automatically\\n' => 'Synchronisez automatiquement les soumissions de formulaires avec vos feuilles de calcul',
  '\\nDrag & drop service account JSON file(s) here\\n' => 'Faites glisser et déposez le(s) fichier(s) JSON du compte de service ici',
  '\\nor click to browse — you can add multiple service accounts at once\\n' => 'i cliquez pour parcourir : vous pouvez ajouter plusieurs comptes de service à la fois',
  '\\nConnected service accounts\\n' => 'Comptes de services connectés',
  '\\nOne-time setup (≈3 min)\\n' => 'Configuration unique (≈3 min)',
  '\\nGo to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create\\n' => 'Accédez à<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ liste déroulante Projet (en haut à gauche) → Nouveau projet → nommez-le → Créer',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>\\n' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong><em>et</em><strong>API Google Drive</strong>',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → name it → Done\\n' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → nommer le → Terminé',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)\\n' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → JSON (téléchargement automatique)',
  '\\nDrag that downloaded file into the box on the left — it is tested automatically\\n' => 'Faites glisser le fichier téléchargé dans la zone de gauche : il est testé automatiquement',
  '\\nAdd<strong>Your Google email</strong>above so created sheets land in your Drive\\n' => 'Ajoutez<strong>Votre e-mail Google</strong>ci-dessus pour que les feuilles créées atterrissent dans votre Drive',
  '\\nPlease choose a valid .json key file.\\n' => 'Veuillez choisir un fichier de clé .json valide.',
  '\\nCould not read file:%s\\n' => 'Impossible de lire le fichier : %s',
  '\\nConnecting service account...\\n' => 'Connexion du compte de service...',
  '\\nService account added.\\n' => 'Compte de service ajouté.',
  '\\nSaved. New sheets created by the plugin will be shared to%sautomatically.\\n' => 'Enregistré. Les nouvelles feuilles créées par le plug-in seront automatiquement partagées avec%s.',
  '\\nEmail cleared. New sheets will stay inside the service account until you share them.\\n' => 'E-mail effacé. Les nouvelles feuilles resteront dans le compte de service jusqu\'à ce que vous les partagiez.',
  '\\nRemove this service account?\\n' => 'Supprimer ce compte de service ?',
  '\\nConnect each form to a specific Google Sheet tab\\n' => 'Connectez chaque formulaire à un onglet Google Sheet spécifique',
  '\\nConnect each form to a specific Google Sheet tab — step by step\\n' => 'Connectez chaque formulaire à un onglet Google Sheet spécifique, étape par étape',
  '\\nNo service account connected.\\n' => 'Aucun compte de service connecté.',
  '\\nGo to the Connections tab and drop a service account JSON key first.\\n' => 'Accédez à l\'onglet Connexions et déposez d\'abord une clé JSON de compte de service.',
  '\\nLast sync OK\\n' => 'Dernière synchronisation OK',
  '\\nLast sync failed\\n' => 'La dernière synchronisation a échoué',
  '\\nRemove sync? The sheet stays safe.\\n' => 'Supprimer la synchronisation ? Le drap reste en sécurité.',
  '\\nYes, remove\\n' => 'Oui, supprimer',
  '\\nRemove this sync (your Google Sheet is not deleted)\\n' => 'Supprimez cette synchronisation (votre feuille Google n\'est pas supprimée)',
  '\\nExisting Bindings\\n' => 'Liaisons existantes',
  '\\nDelete All\\n' => 'Supprimer tout',
  '\\nNew Binding\\n' => 'Nouvelle liaison',
  '\\nSpreadsheet ID\\n' => 'ID de feuille de calcul',
  '\\ntab\\n' => 'tab',
  '\\nChoose Sheet\\n' => 'Choisir une feuille',
  '\\nColumns & Fields\\n' => 'Colonnes et champs',
  '\\nStyle & Save\\n' => 'Styliser et enregistrer',
  '\\nWhich form should send data to Google Sheets?\\n' => 'Quel formulaire doit envoyer des données à Google Sheets ?',
  '\\nPlease select a form first.\\n' => 'Veuillez d\'abord sélectionner un formulaire.',
  '\\nService Account\\n' => 'Compte de service',
  '\\nLoading your spreadsheets...\\n' => 'Chargement de vos feuilles de calcul...',
  '\\nClick<strong>“Browse My Sheets”</strong>to list spreadsheets this service account can already access, or<strong>“Create New Sheet”</strong>to make a fresh one.\\n' => 'Cliquez sur<strong>« Parcourir mes feuilles »</strong>pour répertorier les feuilles de calcul auxquelles ce compte de service peut déjà accéder, ou sur<strong>« Créer une nouvelle feuille »</strong>pour en créer une nouvelle.',
  '\\n<strong>No spreadsheets are accessible to this service account yet.</strong>You have two options:\\n' => '<strong>Aucune feuille de calcul n\'est encore accessible à ce compte de service.</strong>Vous avez deux options :',
  '\\n<strong>Easiest:</strong>click<em>“Create New Sheet”</em>above — it is made for you and shared to your email automatically.\\n' => '<strong>Le plus simple :</strong>cliquez sur<em>"Créer une nouvelle feuille"</em>ci-dessus : elle est créée pour vous et partagée automatiquement sur votre adresse e-mail.',
  '\\n<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste\\n' => '<strong>Utiliser une feuille existante :</strong>l\'ouvrir dans Google Sheets → Partager → coller',
  '\\n→ Editor, then click<em>Browse My Sheets</em>again.\\n' => '→ Éditeur, puis cliquez à nouveau sur<em>Parcourir mes feuilles</em>.',
  '\\nthe service account email\\n' => 'l\'e-mail du compte de service',
  '\\nCreate a new spreadsheet\\n' => 'Créer une nouvelle feuille de calcul',
  '\\nNew spreadsheet title (e.g. Contact form responses)\\n' => 'Nouveau titre de la feuille de calcul (par exemple, réponses au formulaire de contact)',
  '\\nYour Google email — the sheet is shared here so you can open it\\n' => 'Votre adresse e-mail Google : la feuille est partagée ici afin que vous puissiez l\'ouvrir',
  '\\nPre-filled from your saved email.\\n' => 'Pré-rempli à partir de votre e-mail enregistré.',
  '\\nLeave empty only if you don’t need to open the sheet yourself.\\n' => 'Laissez vide uniquement si vous n\'avez pas besoin d\'ouvrir la feuille vous-même.',
  '\\nCreate Sheet\\n' => 'Créer une feuille',
  '\\nCreating...\\n' => 'Création...',
  '\\nCreating spreadsheet...\\n' => 'Création d\'une feuille de calcul...',
  '\\nSheet created and shared with your email. It’s selected below — click Next to finish.\\n' => 'Feuille créée et partagée avec votre email. Il est sélectionné ci-dessous — cliquez sur Suivant pour terminer.',
  '\\nSheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.\\n' => 'Feuille créée. Astuce : ajoutez « Votre adresse e-mail Google » dans l\'onglet Connexions pour que les nouvelles feuilles vous soient automatiquement partagées.',
  '\\nOpen the new sheet\\n' => 'Ouvrez la nouvelle feuille',
  '\\nSelected:\\n' => 'Sélectionné :',
  '\\nLoading worksheet tabs...\\n' => 'Chargement des onglets de la feuille de calcul...',
  '\\nWorksheet Tab\\n' => 'Onglet Feuille de calcul',
  '\\nOr type a new tab name (created automatically)\\n' => 'Ou saisissez un nouveau nom d\'onglet (créé automatiquement)',
  '\\nBrowse My Sheets\\n' => 'Parcourir mes feuilles',
  '\\nCreate New Sheet\\n' => 'Créer une nouvelle feuille',
  '\\nChoose or create a spreadsheet first\\n' => 'Choisissez ou créez d\'abord une feuille de calcul',
  '\\nPlease select a service account.\\n' => 'Veuillez sélectionner un compte de service.',
  '\\nPlease choose or create a spreadsheet first.\\n' => 'Veuillez d\'abord choisir ou créer une feuille de calcul.',
  '\\nEnable Sync for this Form\\n' => 'Activer la synchronisation pour ce formulaire',
  '\\nDisable to pause without deleting the binding\\n' => 'Désactiver la pause sans supprimer la liaison',
  '\\nReading this form’s fields...\\n' => 'Lecture des champs de ce formulaire...',
  '\\nWe couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry —<strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.\\n' => 'Nous n’avons pas pu lire automatiquement les champs de ce formulaire, le mappage des colonnes n’est donc pas disponible. Ne vous inquiétez pas,<strong>chaque champ soumis sera toujours synchronisé automatiquement</strong>, chacun dans sa propre colonne, dans l\'ordre de soumission. La ligne d\'en-tête est créée et mise à jour pour vous.',
  '\\nDrag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.\\n' => 'Faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre des colonnes<strong></strong>. Renommez n\'importe quel en-tête<strong></strong>. Désactivez un champ pour ignorer sa colonne. La lettre (A, B, C...) indique où se situe chaque champ.',
  '\\nCol\\n' => 'Col',
  '\\nSpreadsheet header\\n' => 'En-tête de la feuille de calcul',
  '\\nOrder / On\\n' => 'Commander / Sur',
  '\\nRefresh fields from form\\n' => 'Actualiser les champs du formulaire',
  '\\nColumns & Field Mapping\\n' => 'Mappage des colonnes et des champs',
  '\\nSubmitted time\\n' => 'Heure de soumission',
  'built-in' => 'intégré',
  '\\nSubmitted At\\n' => 'Soumis à',
  '\\nColumn header\\n' => 'En-tête de colonne',
  'Drag to reorder' => 'Faites glisser pour réorganiser',
  '\\nInclude this field\\n' => 'Inclure ce champ',
  '[[\'%dcolumn will be written to the sheet.\', \'en\']]' . chr(0) . '[[\'%dcolumns will be written to the sheet.\', \'en\']]' => 'La colonne %dsera écrite dans la feuille.' . chr(0) . ' Les colonnes %dseront écrites dans la feuille.',
  '\\nSheet Style\\n' => 'Style de feuille',
  '\\n(Google theme)\', \'en\']]' => '(thème Google)',
  '[[\'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.\\n' => 'Choisissez un look pour la feuille : en-tête coloré, ligne supérieure gelée et couleurs de ligne alternées (style propre à Google Sheets). Il est appliqué automatiquement lors de la première synchronisation, ou appliquez-le maintenant.',
  '\\nApply style now\\n' => 'Appliquer le style maintenant',
  '\\nApplying...\\n' => 'Candidature...',
  '\\nOptional — it also applies on the first submission.\\n' => 'Facultatif — cela s\'applique également à la première soumission.',
  '\\nSpreadsheet:\\n' => 'Feuille de calcul :',
  '\\nTab:\\n' => 'Onglet :',
  '\\nColumns:\\n' => 'Colonnes :',
  '\\n%dmapped\\n' => '%dmappé',
  '\\nall submitted fields (auto)\\n' => 'tous les champs soumis (auto)',
  '\\nStyle:\\n' => 'Style :',
  '\\nAfter saving, submit the form once to create the header row and confirm the first sync.\\n' => 'Après avoir enregistré, soumettez le formulaire une fois pour créer la ligne d\'en-tête et confirmer la première synchronisation.',
  '\\nSave Binding\\n' => 'Enregistrer la liaison',
  '[[\'Please choose a spreadsheet first.\\n' => 'Veuillez d\'abord choisir une feuille de calcul.',
  '\\nPick a style first — “None” leaves the sheet unstyled.\\n' => 'Choisissez d\'abord un style : "Aucun" laisse la feuille sans style.',
  '\\nStyle applied.\\n' => 'Style appliqué.',
  '\\nPlease select a form.\\n' => 'Veuillez sélectionner un formulaire.',
  '\\nPlease choose a spreadsheet.\\n' => 'Veuillez choisir une feuille de calcul.',
  '\\nBinding saved.\\n' => 'Liaison enregistrée.',
  '\\nRemove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.\\n' => 'Supprimer cette liaison ? La synchronisation s\'arrête pour ce formulaire. Votre feuille Google Sheet et ses données ne sont pas supprimées.',
  '\\nSync removed — your Google Sheet and its data are untouched.\\n' => 'Sync supprimée : votre feuille Google et ses données restent intactes.',
  '[[\'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' . chr(0) . '[[\'Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' => 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.' . chr(0) . 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.',
  '\\nAll bindings removed. Your Google Sheets are untouched.\\n' => 'Toutes les liaisons ont été supprimées. Vos feuilles Google Sheets sont intactes.',
  '\\nHelp & Setup Guide\\n' => 'Aide et guide de configuration',
  '\\nEverything you need to connect forms to Google Sheets\\n' => 'Tout ce dont vous avez besoin pour connecter des formulaires à Google Sheets',
  '\\nStep-by-Step Setup\\n' => 'Configuration étape par étape',
  '\\nCreate or Select a Project\\n' => 'Créer ou sélectionner un projet',
  '\\nOpen console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create\', \'en\']]' => 'Ouvrez console.cloud.google.com et connectez-vous → cliquez sur le menu déroulant Projet (en haut à gauche) → Nouveau projet (ou choisissez-en un existant) → saisissez un nom → Créer',
  '\\nEnable both Google APIs\\n' => 'Activer les deux API Google',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)\\n' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong>et<strong>API Google Drive</strong>(les deux sont obligatoires : Drive répertorie et crée les fichiers)',
  '\\nCreate a Service Account\\n' => 'Créer un compte de service',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done\\n' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → saisir un nom → Terminé',
  '\\nCreate a JSON Key\\n' => 'Créer une clé JSON',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)\\n' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → choisissez JSON (téléchargement automatique des fichiers)',
  '\\nDrop the Key File\\n' => 'Supprimez le fichier clé',
  '\\nDrag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge\\n' => 'Faites glisser le fichier téléchargé dans l\'onglet Connexions : il est vérifié automatiquement et vous verrez un badge vert "Connecté"',
  '\\nAdd Your Google Email\\n' => 'Ajoutez votre adresse e-mail Google',
  '\\nOn the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive\\n' => 'Dans l\'onglet Connexions, remplissez "Votre e-mail Google" et enregistrez : les feuilles créées par le plugin vous sont ensuite partagées afin qu\'elles apparaissent dans votre propre Drive',
  '\\nBind a Form (create a sheet)\\n' => 'Lier un formulaire (créer une feuille)',
  '\\nForm Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path\\n' => 'Liaisons de formulaire → choisir un formulaire →<strong>Créer une nouvelle feuille</strong>→ Enregistrer. Aucun partage manuel n\'est nécessaire : c\'est le chemin le plus simple',
  '\\n...or use an existing sheet\\n' => '...ou utiliser une feuille existante',
  '\\nPrefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard", \'en\']]' => 'Vous préférez votre propre feuille ? Ouvrez-le → Partager → collez l\'e-mail du compte de service (bouton copier sur sa carte) → Éditeur → puis Parcourir mes feuilles dans l\'assistant',
  'FAQ' => 'FAQ',
  '\\nI created a sheet — where did it go?\\n' => 'J\'ai créé une feuille : où est-elle passée ?',
  '\\nService accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.\\n' => 'Les comptes de service créent des fichiers dans leur propre Drive masqué. Ajoutez « Votre e-mail Google » dans l’onglet Connexions et le plugin vous partage automatiquement chaque nouvelle feuille – elle apparaît ensuite sous « Partagé avec moi » dans votre Google Drive. Chaque feuille comporte également un lien « Ouvrir » directement dans ce tableau de bord.',
  '\\nWhy don’t I see my existing sheet in the picker?\\n' => 'Pourquoi ma feuille existante ne s\'affiche-t-elle pas dans le sélecteur ?',
  '\\nIt must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.\\n' => 'Il doit d\'abord être partagé avec l\'email du compte de service : ouvrir la feuille → Partager → coller l\'email (utiliser le bouton copier sur la carte de connexion) → définir l\'Editeur → Partager. Cliquez ensuite à nouveau sur « Parcourir mes feuilles ».',
  '\\nTest result: Google API is not enabled.\\n' => 'Résultat du test : l\'API Google n\'est pas activée.',
  '\\nOpen Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.\\n' => 'Ouvrez Google Cloud Console pour le même projet → API et services → Bibliothèque, et activez À LA FOIS « API Google Sheets » et « API Google Drive ». Attendez une minute, puis retestez.',
  '\\nTest result: Access/Permission denied\\n' => 'Résultat du test : Accès/Autorisation refusée',
  '\\nThe service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.\\n' => 'Le compte de service peut s\'authentifier mais ne peut pas accéder à cette feuille de calcul spécifique. Partagez à nouveau la feuille avec l\'adresse e-mail du compte de service en tant qu\'éditeur, ou créez plutôt une nouvelle feuille.',
  '\\nOpenSSL is required.\\n' => 'OpenSSL est requis.',
  '\\nThe server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.\\n' => 'Le serveur ne dispose pas de l\'extension PHP OpenSSL utilisée pour signer la requête sécurisée de Google. Demandez à votre hébergeur de l\'activer : aucun paramètre de plug-in ne peut le remplacer.',
  '\\nCan I connect more than one service account?\\n' => 'Puis-je connecter plusieurs comptes de service ?',
  '\\nYes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.\\n' => 'Oui : déposez autant de clés JSON que vous le souhaitez dans l\'onglet Connexions et choisissez celle que chaque liaison de formulaire doit utiliser.',
  '[[\'Does the connection expire?\\n' => 'La connexion expire-t-elle ?',
  '\\nNo. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.\\n' => 'Non. L\'intégration s\'exécute entièrement sur le serveur à l\'aide de votre clé JSON : aucune session de navigateur ni connexion ne doit expirer.',
  '\\nCan I choose which field goes to which column?\\n' => 'Puis-je choisir quel champ va à quelle colonne ?',
  '\\nYes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.\\n' => 'Oui. À l\'étape<strong>Colonnes et champs</strong>de l\'assistant de liaison, faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre, renommez chaque en-tête de colonne et désactivez n\'importe quel champ pour l\'ignorer. Le badge A/B/C indique exactement où atterrit chaque champ.',
  '\\nCan I style the sheet automatically?\\n' => 'Puis-je styliser la feuille automatiquement ?',
  '\\nYes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.\\n' => 'Oui. L\'étape<strong>Style & Save</strong>propose des thèmes Google-Sheets (en-tête coloré, ligne supérieure gelée, couleurs de ligne alternées). Choisissez-en un et il sera appliqué lors de la première synchronisation, ou cliquez sur "Appliquer le style maintenant".',
  '\\nWhat if my form fields change later?\\n' => 'Que se passe-t-il si les champs de mon formulaire changent ultérieurement ?',
  '\\nNew fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.\\n' => 'De nouveaux champs sont ajoutés automatiquement. En mode mappé, ouvrez l\'étape Colonnes et cliquez sur « Actualiser les champs du formulaire » pour les intégrer dans le mappage ; en mode « Tous les champs du formulaire », ils apparaissent sous forme de nouvelles colonnes lors de la prochaine soumission.',
  '\\nWhat if the tab doesn’t exist yet?\\n' => 'Que se passe-t-il si l\'onglet n\'existe pas encore ?',
  '\\nIt is created automatically the first time a submission is synced.\\n' => 'Il est créé automatiquement la première fois qu\'une soumission est synchronisée.',
  '\\nGoogle Sheet Sync Logs\\n' => 'Journaux de synchronisation Google Sheet',
  '\\nLatest submissions sent to Google Sheets, success or failure\\n' => 'Dernières soumissions envoyées à Google Sheets, succès ou échec',
  '\\nLog cleared.\\n' => 'Journal effacé.',
  '\\nClear Log\\n' => 'Effacer le journal',
  '\\nClear all logs?\\n' => 'Effacer tous les journaux ?',
  '\\nNo sync activity yet.\\n' => 'Aucune activité de synchronisation pour l\'instant.',
  'Event' => 'Événement',
  '\\nSpreadsheet\\n' => 'Feuille de calcul',
  'Detail' => 'Détail',
  '\\nsynchronized\\n' => 'synchronisé',
  '\\nNone (plain)\\n' => 'Aucun (simple)',
  '\\nMinimal\\n' => 'Minimal',
  '\\nSlate\\n' => 'Ardoise',
  '\\nSunset\\n' => 'Coucher de soleil',
  '\\nGrape\\n' => 'Raisin',
  '\\n%sis currently unavailable.\\n' => '%sest actuellement indisponible.',
  '\\ndisabled in php.ini:%s\\n' => 'désactivé dans php.ini : %s',
  '\\nnot provided by PHP or its required extension:%s\\n' => 'non fourni par PHP ou son extension requise : %s',
  '\\n%1$scannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.\\n' => '%1$sne peut pas s\'exécuter car les fonctions PHP requises ne sont pas disponibles (%2$s). Demandez à votre fournisseur d\'hébergement d\'activer l\'extension PHP requise ou supprimez les fonctions répertoriées de Disabled_functions dans php.ini.',
  'Panel' => 'Panneau',
  '\\nThis add-on is not included in Flux Forms.\\n' => 'Ce module complémentaire n\'est pas inclus dans Flux Forms.',
  '\\nError: server (%s) responded with an invalid request. responded code :%s\\n' => 'Erreur : le serveur (%s) a répondu avec une requête non valide. code répondu : %s',
  '\\nYour Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.\\n' => 'Votre abonnement Easy Form Builder Pro a expiré, ce module complémentaire ne peut donc pas être téléchargé.',
  '\\nSomething went wrong, please refresh the page.\\n' => 'Quelque chose s\'est mal passé, veuillez actualiser la page.',
  '\\nThe response attachment could not be verified. Please attach the file again.\\n' => 'La réponse en pièce jointe n\'a pas pu être vérifiée. Veuillez joindre à nouveau le fichier.',
  '\\nYou do not have permission to update these settings.", \'en\']]' => 'Vous n\'êtes pas autorisé à mettre à jour ces paramètres.',
  '\\nPlease enter a valid admin email address.\\n' => 'Veuillez saisir une adresse e-mail d\'administrateur valide.',
  '\\nYou do not have permission to complete setup.\\n' => 'Vous n\'êtes pas autorisé à terminer la configuration.',
  '\\nInvalid email address\\n' => 'Adresse e-mail invalide',
  'Please enter a valid email address.' => 'Veuillez saisir une adresse e-mail valide.',
  '\\nInvalid sender email\\n' => 'E-mail de l\'expéditeur invalide',
  '\\nThe sender email address is not valid.\\n' => 'L\'adresse e-mail de l\'expéditeur n\'est pas valide.',
  '\\nEmail tester service error\\n' => 'Erreur du service de testeur de messagerie',
  '\\nCould not start email test.\\n' => 'Impossible de démarrer le test de messagerie.',
  '\\nInvalid service response\\n' => 'Réponse du service invalide',
  '\\nThe email tester service returned an invalid response.\\n' => 'Le service de test de courrier électronique a renvoyé une réponse non valide.',
  '\\nThe message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.\\n' => 'Le message n\'a jamais quitté votre site Web : WordPress a signalé une erreur lors de la tentative de l\'envoyer. C\'est le seul cas où le correctif se situe réellement du côté de WordPress ou de l\'hébergement - généralement un plugin SMTP ou une messagerie PHP désactivée par l\'hôte.',
  '\\nWordPress could not send the test email. The message never left your website, so nothing was delivered.\\n' => 'WordPress n\'a pas pu envoyer l\'e-mail de test. Le message n\'a jamais quitté votre site Web, donc rien n\'a été livré.',
  '[[\'Email test is waiting for delivery confirmation\\n' => 'Le test d\'e-mail attend la confirmation de livraison',
  '\\nWordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.\\n' => 'WordPress a envoyé l\'e-mail de test. Flux Forms attend le résultat de la livraison avant de marquer l\'e-mail comme prêt.',
  '\\nWordPress accepted and sent the test email. Waiting for it to arrive.\\n' => 'WordPress a accepté et envoyé l\'e-mail de test. En attendant qu\'il arrive.',
  '\\nThe email tester service returned an invalid JSON response.\\n' => 'Le service de test d\'e-mail a renvoyé une réponse JSON non valide.',
  '\\nThe email tester service could not start the test.\\n' => 'Le service de test de courrier électronique n\'a pas pu démarrer le test.',
  '\\nInvalid test hash\\n' => 'Hash de test invalide',
  '\\nThe email test hash is not valid.\\n' => 'Le hachage de test de l\'e-mail n\'est pas valide.',
  '\\nYour site could not connect\\n' => 'Votre site n\'a pas pu se connecter',
  '[[\'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.\\n' => 'Aucune connexion n\'a pu être établie depuis votre site vers notre service de test de messagerie. Il s\'agit généralement d\'un trafic sortant bloqué par votre serveur ou son réseau (certains hôtes bloquent les connexions vers d\'autres pays) plutôt que d\'un problème avec le service. Votre fournisseur d\'hébergement peut le confirmer.',
  '\\nService error\\n' => 'Erreur de service',
  '\\nThe email tester service could not return the result.\\n' => 'Le service de test de courrier électronique n\'a pas pu renvoyer le résultat.',
  '\\nThe message never left your website. WordPress reported an error while sending, so nothing could be delivered.\\n' => 'Le message n\'a jamais quitté votre site Web. WordPress a signalé une erreur lors de l\'envoi, rien n\'a donc pu être livré.',
  '\\nThe email was sent, but it never arrived\\n' => 'L\'e-mail a été envoyé, mais il n\'est jamais arrivé',
  '\\nWordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.\\n' => 'WordPress a envoyé le message avec succès, donc votre site et ce plugin ont fait leur part. Il a été perdu, retardé ou rejeté après avoir quitté WordPress - généralement le côté destinataire l\'a traité comme du spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante.',
  '\\nEmail test failed\', \'en\']]' => 'Le test de messagerie a échoué',
  '\\nThe email server test could not verify email capability.\\n' => 'Le test du serveur de messagerie n\'a pas pu vérifier la fonctionnalité de messagerie.',
  '\\nEmail capability verified\\n' => 'Capacité de messagerie vérifiée',
  '\\nServer confirmed ability to send emails.\\n' => 'Le serveur a confirmé sa capacité à envoyer des e-mails.',
  '\\nYour emails are being delivered to spam\\n' => 'Vos e-mails sont envoyés dans les spams',
  '\\nWordPress sent the test email, but delivery has not been confirmed yet.\\n' => 'WordPress a envoyé l\'e-mail de test, mais la livraison n\'a pas encore été confirmée.',
  '\\nEmail delivery failed:%s\\n' => 'Échec de l\'envoi de l\'e-mail : %s',
  '\\nNo file was received. Please choose a file and try again.\\n' => 'Aucun fichier n\'a été reçu. Veuillez choisir un fichier et réessayer.',
  '\\nThe file could not be read. Please try attaching it again.\\n' => 'Le fichier n\'a pas pu être lu. Veuillez réessayer de le joindre.',
  '\\nEnable the Email Notification Feature\\n' => 'Activer la fonctionnalité de notification par e-mail',
  '\\nTo receive email notifications from your forms, verify your email server by following these steps:\\n' => 'Pour recevoir des notifications par e-mail à partir de vos formulaires, vérifiez votre serveur de messagerie en suivant ces étapes :',
  '\\nGo to the<a href="%s" style="font-weight:600;">Flux Forms Panel</a>\\n' => 'Accédez au panneau Flux Forms<a href="%s" style="font-weight:600;"></a>',
  '\\nClick Settings from the top menu\\n' => 'Cliquez sur Paramètres dans le menu supérieur',
  '\\nSelect the Email Settings tab\\n' => 'Sélectionnez l\'onglet Paramètres de messagerie',
  '\\nClick "Check Email Server" and wait for the test to finish\\n' => 'Cliquez sur "Vérifier le serveur de messagerie" et attendez la fin du test',
  '\\nIf the score is above 70 — enable the "This site can send emails" switch and save\\n' => 'Si le score est supérieur à 70 : activez le bouton "Ce site peut envoyer des e-mails" et enregistrez',
  '\\nOtherwise, follow the instructions shown in the test results\\n' => 'Sinon, suivez les instructions indiquées dans les résultats du test',
  '\\n%snotification\\n' => 'Notification%s',
  '\\nDisabling this feature may affect the proper functionality of Flux Forms. If you plan to use the%sfeature, please ensure it is enabled.\\n' => 'La désactivation de cette fonctionnalité peut affecter le bon fonctionnement de Flux Forms. Si vous envisagez d\'utiliser la fonctionnalité%s, assurez-vous qu\'elle est activée.',
  '\\nEmail system is working properly.\\n' => 'Le système de messagerie fonctionne correctement.',
  '\\nYour server is able to send emails using the default PHP mail system.\', \'en\']]' => 'Votre serveur est capable d\'envoyer des e-mails en utilisant le système de messagerie PHP par défaut.',
  '\\nEmail system is not available.\\n' => 'Le système de messagerie n\'est pas disponible.',
  '\\nThe PHP mail() function is missing. Your server cannot send emails.\\n' => 'La fonction PHP mail() est manquante. Votre serveur ne peut pas envoyer d\'e-mails.',
  '\\nEmail sending is blocked by server settings.\\n' => 'L\'envoi d\'e-mails est bloqué par les paramètres du serveur.',
  '\\nThe mail() function is disabled in your server PHP configuration (php.ini).\\n' => 'La fonction mail() est désactivée dans la configuration PHP de votre serveur (php.ini).',
  '\\nWordPress mail function not found.\\n' => 'Fonction de messagerie WordPress introuvable.',
  '\\nThe wp_mail() function is missing or not available. WordPress email features may be broken.\\n' => 'La fonction wp_mail() est manquante ou non disponible. Les fonctionnalités de messagerie WordPress peuvent être interrompues.',
  '\\nNo email handler configured.\\n' => 'Aucun gestionnaire de messagerie configuré.',
  '\\nYour server has no SMTP host or sendmail path set. Emails may not be delivered.\\n' => 'Votre serveur n\'a pas d\'hôte SMTP ou de chemin sendmail défini. Les e-mails risquent de ne pas être livrés.',
  '\\nTest email could not be sent.\\n' => 'L\'e-mail de test n\'a pas pu être envoyé.',
  '\\nIt seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.\\n' => 'Il semble que votre site WordPress n\'ait pas pu envoyer d\'e-mail de test. Pour tester manuellement votre système de messagerie, accédez à Flux Forms > Paramètres > onglet Paramètres de messagerie et cliquez sur le bouton « Vérifier le serveur de messagerie ».',
  '\\nInvalid email address.\\n' => 'Adresse e-mail invalide.',
  '\\nPlease enter a valid admin email address before testing email delivery.\\n' => 'Veuillez saisir une adresse e-mail d\'administrateur valide avant de tester la livraison des e-mails.',
  '\\nInvalid sender email.\\n' => 'E-mail de l\'expéditeur invalide.',
  '\\nThe sender email address is not valid. Please check your email settings.\\n' => 'L\'adresse e-mail de l\'expéditeur n\'est pas valide. Veuillez vérifier vos paramètres de messagerie.',
  '\\nEmail tester service error.\\n' => 'Erreur du service de testeur de messagerie.',
  '\\nFlux Forms could not start the email delivery test. Please try again later.\\n' => 'Flux Forms n\'a pas pu démarrer le test de livraison des e-mails. Veuillez réessayer plus tard.',
  '\\nInvalid email tester response.\', \'en\']]' => 'Réponse du testeur d\'e-mail non valide.',
  '\\nInvalid email test.\\n' => 'Test d\'e-mail non valide.',
  '\\nThe email test identifier is invalid. Please start a new test.\\n' => 'L\'identifiant du test de courrier électronique n\'est pas valide. Veuillez démarrer un nouveau test.',
  '\\nEmail tester connection error.\\n' => 'Erreur de connexion du testeur de messagerie.',
  '\\nFlux Forms could not connect to the email tester service.\\n' => 'Flux Forms n\'a pas pu se connecter au service de testeur de courrier électronique.',
  '\\nEmail delivery test failed.\\n' => 'Le test de remise des e-mails a échoué.',
  '\\nYour emails are arriving in the spam folder.\\n' => 'Vos e-mails arrivent dans le dossier spam.',
  '\\nThe test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.\\n' => 'Le message de test a été livré, mais son score de délivrabilité est trop faible pour être fiable. L\'envoi via SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine résolvent ce problème.',
  '\\nEmail delivery test is pending.\\n' => 'Le test de livraison des e-mails est en attente.',
  '\\nEmail Issue\\n' => 'Problème de courrier électronique',
  '\\nFlux Forms Email Warning:\\n' => 'Avertissement par e-mail Flux Forms :',
  '\\nPlan data is missing.\\n' => 'Les données du plan sont manquantes.',
  '\\nInvalid plan data format.\\n' => 'Format de données du plan non valide.',
  '\\nInvalid plan type.\\n' => 'Type de forfait non valide.',
  '\\nPlease confirm this plan downgrade before continuing.\\n' => 'Veuillez confirmer ce forfait avant de continuer.',
  '\\nFree plan activated - no additional features.\\n' => 'Forfait gratuit activé - aucune fonctionnalité supplémentaire.',
  '\\nFree Plus plan activated with enhanced features.\\n' => 'Forfait Free Plus activé avec des fonctionnalités améliorées.',
  '\\nPro plan activated with existing activation code.\\n' => 'Forfait Pro activé avec le code d\'activation existant.',
  '\\nRedirecting to Pro plan purchase page.\\n' => 'Redirection vers la page d\'achat du forfait Pro.',
  '\\nPlan "%s" has been successfully processed.\\n' => 'Le plan "%s" a été traité avec succès.',
  '\\nAddon Installation Issue\\n' => 'Problème d\'installation du module complémentaire',
  '\\nTechnical Details\\n' => 'Détails techniques',
  '\\nChecked%s\\n' => 'Vérifié%s',
  '\\nSystem Ready\\n' => 'Système prêt',
  '\\nChecking add-on installation capabilities...\', \'en\']]' => 'Vérification des capacités d\'installation des modules complémentaires...',
  '\\nThis check runs once after plugin activation. Please refresh the page in a few moments.\\n' => 'Cette vérification s\'exécute une fois après l\'activation du plugin. Veuillez actualiser la page dans quelques instants.',
  '\\nSome add-ons need a PHP server change\\n' => 'Certains modules complémentaires nécessitent un changement de serveur PHP',
  '\\nFlux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.\\n' => 'Flux Forms a mis en pause en toute sécurité chaque module complémentaire actif concerné, afin que le reste du plugin puisse continuer à fonctionner.',
  '\\n(currently enabled and paused)\\n' => '(actuellement activé et mis en pause)',
  '\\n(not enabled)\\n' => '(non activé)',
  '\\ndisabled in php.ini:\\n' => 'désactivé dans php.ini :',
  '[["not provided by PHP or its required extension:\\n' => 'non fourni par PHP ou son extension requise :',
  '\\nThis usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.\\n' => 'Cela signifie généralement que l\'extension PHP nécessaire n\'est pas installée ou que la fonction est répertoriée dans Disable_functions dans php.ini. Veuillez demander à votre fournisseur d\'hébergement de l\'activer, puis actualisez cette page.',
  '\\nIf you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.\\n' => 'Si vous voyez ce message, c\'est probablement pour l\'une des raisons suivantes : Si un plug-in de mise en cache est installé, ses paramètres devront peut-être être révisés.',
  '\\nPlease also ensure that you have a stable internet connection and try again.\\n' => 'Veuillez également vous assurer que vous disposez d\'une connexion Internet stable et réessayer.',
  'File' => 'Fichier',
  '\\nBuilt with%sYT Form%sby%sWordPress form plugin by whitestudio.team%s\\n' => 'Construit avec%sYT Form%spar%sPlugin de formulaire WordPress par whitestudio.team%s',
  '\\nFree WordPress form plugin\\n' => 'Plugin de formulaire WordPress gratuit',
  '\\nPowered by%1$sYT Form%2$s.%3$sbest Form plugin for Wordpress%4$s.\\n' => 'Propulsé par%1$sYT Form%2$s.%3$smeilleur plugin de formulaire pour Wordpress%4$s.',
  '\\nFlux Forms WordPress Plugin\\n' => 'Plugin WordPress Flux Forms',
  '\\nThis form requires a payment method. Please add one or change the form type.\\n' => 'Ce formulaire nécessite un mode de paiement. Veuillez en ajouter un ou modifier le type de formulaire.',
  '\\nError Monitor\\n' => 'Moniteur d\'erreurs',
  'Theme' => 'Thème',
  '\\nWordPress Core\\n' => 'WordPress Core',
  'External' => 'Externe',
  'Unknown' => 'Inconnu',
  'Notice' => 'Avis',
  '\\nLine\\n' => 'Ligne',
  '\\nNo errors detected\\n' => 'Aucune erreur détectée',
  '\\nThese errors may interfere with forms built using Flux Forms.\\n' => 'Ces erreurs peuvent interférer avec les formulaires créés à l\'aide de Flux Forms.',
  '\\nThis panel is only visible to site administrators.\\n' => 'Ce panneau n\'est visible que par les administrateurs du site.',
  '\\njQuery Dependency Issue\\n' => 'jProblème de dépendance de requête',
  '\\njQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.\\n' => 'jQuery n\'est pas correctement chargé ou disponible. Les fonctionnalités AJAX et des formulaires interactifs peuvent ne pas fonctionner correctement.',
  '\\nWhiteStudio.team\\n' => 'WhiteStudio.équipe',
  '\\nEFB\\n' => 'EFB',
  '[[\'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.\\n' => 'Flux Forms est un plugin de création de formulaires WordPress gratuit et puissant permettant de créer des formulaires de contact, des formulaires de paiement, des enquêtes, des formulaires d\'inscription, des formulaires en plusieurs étapes, des formulaires de téléchargement de fichiers, des formulaires de signature électronique et des formulaires d\'enregistrement audio, vidéo et d\'écran, avec logique conditionnelle, notifications par e-mail, intégrations, gestion des entrées et protection anti-spam avancée.',
  '\\nWordPress Form Builder Plugin\\n' => 'Plugin de création de formulaires WordPress',
  '\\nWordPress 5.0 or later; PHP 7.0 or later\\n' => 'WordPress 5.0 ou version ultérieure ; PHP 7.0 ou version ultérieure',
  '\\nFlux Forms Documentation\\n' => 'Documentation Flux Forms',
  '\\nDrag-and-Drop WordPress Form Builder\\n' => 'Générateur de formulaires WordPress par glisser-déposer',
  '\\nUnlimited Forms and Form Entries\', \'en\']]' => 'Formulaires et entrées de formulaire illimités',
  '\\nResponsive and RTL-Friendly Forms\\n' => 'Formulaires réactifs et compatibles RTL',
  '\\nContact and Inquiry Forms\\n' => 'Formulaires de contact et de demande de renseignements',
  '\\nSupport and Feedback Forms with Message Tracking\\n' => 'Formulaires d\'assistance et de commentaires avec suivi des messages',
  '\\nSurvey and Poll Forms with Visual Results\\n' => 'Formulaires d\'enquête et de sondage avec résultats visuels',
  '\\nStripe and PayPal Payment Forms\\n' => 'Formulaires de paiement Stripe et PayPal',
  '\\nWordPress Login and Registration Forms\\n' => 'Formulaires de connexion et d\'inscription WordPress',
  '\\nFile Upload Forms\\n' => 'Formulaires de téléchargement de fichiers',
  '\\nAudio Recording Forms\\n' => 'Formulaires d\'enregistrement audio',
  '\\nVideo Recording Forms\\n' => 'Formulaires d\'enregistrement vidéo',
  '\\nScreen Recording Forms with Optional Microphone Audio\\n' => 'Formulaires d\'enregistrement d\'écran avec microphone audio en option',
  '\\nPrivate and Restricted-Access Forms\\n' => 'Formulaires privés et à accès restreint',
  '\\nMulti-Step Forms\\n' => 'Formulaires en plusieurs étapes',
  '\\nSmart Forms with Conditional Logic\\n' => 'Formulaires intelligents avec logique conditionnelle',
  '\\nElectronic Signature Forms\\n' => 'Formulaires de signature électronique',
  '\\nLocation Picker Forms with OpenStreetMap and Leaflet\\n' => 'Formulaires de sélection d\'emplacement avec OpenStreetMap et Leaflet',
  '\\nJob Application Forms\\n' => 'Formulaires de demande d\'emploi',
  '\\nEvent Registration Forms\\n' => 'Formulaires d\'inscription à un événement',
  '\\nOrder Forms with Recurring and Subscription Billing\', \'en\']]' => 'Formulaires de commande avec facturation récurrente et par abonnement',
  '\\nDrag-and-Drop File Upload Fields\\n' => 'Champs de téléchargement de fichiers par glisser-déposer',
