  '\\nIf your emails are not being delivered, try using an SMTP plugin. For more information,%1$sclick here%2$sor contact our%3$ssupport team%4$s.\\n' => 'Si vos e-mails ne sont pas livrés, essayez d\'utiliser un plugin SMTP. Pour plus d\'informations, %1$scliquez ici%2$sou contactez notre équipe d\'assistance%3$s%4$s.',
