  '\\n%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.\\n' => ' Le formulaire%dcontient reCAPTCHA mais la clé du site ou la clé secrète est manquante ; le formulaire n\'est pas affiché.' . chr(0) . ' Les formulaires%dont reCAPTCHA activé mais la clé du site ou la clé secrète est manquante ; ils ne sont pas affichés.',
  '\\nForm\\x00Forms\\n' => 'Formulaire' . chr(0) . 'Formulaires',
