  '\\nRemove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.\\n' => 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.' . chr(0) . 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.',
  '\\nYou can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.\\n' => 'Vous pouvez joindre jusqu\'au fichier%1$dici. Veuillez patienter environ%2$dminutes avant de réessayer.' . chr(0) . 'Vous pouvez joindre jusqu\'à%1$ddes fichiers ici. Veuillez patienter environ%2$dminutes avant de réessayer.',
  '\\nfield\\x00fields\\n' . chr(0) . '\\nfield\\x00fields\\n' => 'field' . chr(0) . 'fields',
