  '[[\'%dautomation is on.\\x00%dautomations are on.\\n' . chr(0) . '[[\'%dautomation is on.\\x00%dautomations are on.\\n' => ' L\'automatisation %dest activée.' . chr(0) . ' Les automatisations %dsont activées.',
  '\\n%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.\\n' . chr(0) . '\\n%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.\\n' => ' L\'exécution de%da échoué au cours des 7 derniers jours ; voir le journal d\'exécution.' . chr(0) . ' Les exécutions%dont échoué au cours des 7 derniers jours ; voir le journal d\'exécution.',
