  '\\nForm\\x00Forms\\n' . chr(0) . '\\nForm\\x00Forms\\n' => 'Formulaire' . chr(0) . 'Formulaires',
  '[[\'%dservice account connected\\x00%dservice accounts connected\\n' . chr(0) . '[[\'%dservice account connected\\x00%dservice accounts connected\\n' => 'Compte de service %dconnecté' . chr(0) . ' Comptes de service %dconnectés',
  '\\n%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.\\n' . chr(0) . '\\n%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.\\n' => 'La colonne%dsera écrite dans la feuille.' . chr(0) . ' Les colonnes%dseront écrites dans la feuille.',
