  'Your test email was sent, but delivery is not confirmed yet. Check the inbox or spam folder for the address below; you can finish setup and try again later from General Settings.' => 'Votre e-mail de test a été envoyé, mais la livraison n\'est pas encore confirmée. Vérifiez la boîte de réception ou le dossier spam pour l\'adresse ci-dessous ; vous pouvez terminer la configuration et réessayer plus tard à partir des paramètres généraux.',
