  'It is not possible to include reCAPTCHA on payment forms.' => 'Il n\'est pas possible d\'inclure reCAPTCHA sur les formulaires de paiement.',
  'This site can send emails' => 'Ce site peut envoyer des e-mails',
  'Weekly email health and form activity report' => 'Rapport hebdomadaire sur l\'état des e-mails et l\'activité des formulaires',
  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Ajoute le total de vos activités de formulaire (formulaires, vues et soumissions) à l\'e-mail hebdomadaire que votre site envoie à l\'administrateur principal. Ces totaux sont lus sur votre propre site et ne sont jamais envoyés à WhiteStudio.',
  'No automated email check has run yet.' => 'Aucune vérification automatique des e-mails n\'a encore été exécutée.',
  'Collect email delivery statistics' => 'Collecter des statistiques de livraison d\'e-mails',
  'Counts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.' => 'Compte le nombre d\'e-mails envoyés ou ayant échoué, les affiche dans le widget du tableau de bord et ajoute la section d\'état de livraison des e-mails à l\'e-mail hebdomadaire. Une fois par semaine, votre site effectue un test de livraison et rapporte le résultat. Seuls les utilisateurs Pro peuvent désactiver cette fonctionnalité.',
  'Interval' => 'Intervalle',
  'Next Billing Date' => 'Date de facturation suivante',
  'Yearly' => 'Annuelle',
  'How to activate the Pro version of Flux Forms' => 'Comment activer la version Pro de Flux Forms',
  'Uploaded File' => 'Fichier téléchargé',
  'Your internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.' => 'Votre connexion Internet a été perdue, mais ne vous inquiétez pas, nous avons enregistré les informations que vous avez saisies sur ce formulaire. Une fois que vous êtes reconnecté à Internet, vous pouvez facilement envoyer vos informations en cliquant sur le bouton Soumettre.',
  'Please ensure that you have a stable internet connection and try again.' => 'Veuillez vous assurer que vous disposez d\'une connexion Internet stable et réessayer.',
  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => 'Un problème est survenu lors du téléchargement du fichier et le formulaire n\'a pas été soumis. Veuillez vérifier que votre connexion Internet est stable et réessayer.',
  'You are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)' => 'Vous rencontrez des problèmes avec jQuery. Veuillez contacter l\'administrateur pour obtenir de l\'aide. (Code d\'erreur : JQ-500)',
