  'Please wait, you will be redirected shortly.' => 'Veuillez patienter, vous serez redirigé sous peu.',
  'Persia payment' => 'Paiement Perse',
  'Unlock Pro Features Today' => 'Débloquez les fonctionnalités Pro aujourd\'hui',
  'Upgrade to Pro for just %1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => ' Passez à Pro pour seulement %1$s%2$s %3$s/ an et accédez à des fonctionnalités puissantes, notamment des champs de formulaire avancés, des intégrations de paiement, une logique conditionnelle, des formulaires en plusieurs étapes, des téléchargements de fichiers, la sécurité et la protection anti-spam et une assistance prioritaire.%4$sAfficher les fonctionnalités Pro%5$s',
  'Add-on' => 'Module complémentaire',
  'Add-ons' => 'Modules complémentaires',
  'Stripe Payment Add-on' => 'Module complémentaire de paiement Stripe',
  'The Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.' => 'Le module complémentaire Stripe pour Flux Forms vous permet d\'intégrer votre site WordPress à Stripe pour le traitement des paiements, les dons et les commandes en ligne.',
  'Offline Forms Add-on' => 'Module complémentaire Formulaires hors ligne',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => 'Le module complémentaire Offline Forms pour Flux Forms permet aux utilisateurs d\'enregistrer leur progression lorsqu\'ils remplissent des formulaires dans des situations hors ligne.',
  'Please update Flux Forms before trying again.' => 'Veuillez mettre à jour Flux Forms avant de réessayer.',
  'Activation of offline form mode.' => 'Activation du mode formulaire hors ligne.',
  'Before activating this option, install' => 'Avant d\'activer cette option, installez',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => 'Pour créer un formulaire de paiement permettant de collecter des paiements en ligne, vous devez d\'abord installer un module complémentaire de paiement tel que le module complémentaire Stripe.',
  'All formats' => 'Tous les formats',
  'EFB SMS Add-on' => 'Module complémentaire SMS EFB',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => 'Activez la fonctionnalité SMS dans vos formulaires avec le module complémentaire EFB SMS, vous permettant de valider des numéros de mobile et d\'envoyer des codes de confirmation par SMS, ainsi que de recevoir des notifications via le service SMS.',
  'Advanced confirmation code Add-on' => 'Module complémentaire de code de confirmation avancé',
  'Send a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.' => 'Envoyez un code de confirmation par e-mail ou SMS aux utilisateurs et/ou administrateurs, leur permettant d\'accéder rapidement aux nouvelles réponses.',
  'Box Checklist' => 'Liste de contrôle des cases',
  'Radio Checklist' => 'Liste de contrôle radio',
  'This is a warning for WPBakery users. For more information, please click here.' => 'Ceci est un avertissement pour les utilisateurs de WPBakery. Pour plus d\'informations, veuillez cliquer ici.',
  'Are you sure you want to close replies to this message?' => 'Êtes-vous sûr de vouloir fermer les réponses à ce message ?',
  'Are you sure you want to open the responses to this message?' => 'Êtes-vous sûr de vouloir ouvrir les réponses à ce message ?',
  'The response has been closed by Admin.' => 'La réponse a été fermée par l\'administrateur.',
