  'Install the add-on' => 'Installer le module complémentaire',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons' => 'Veuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Jalili',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons' => 'Veuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Hijri',
  'date & time' => 'date et heure',
  'Enable file upload in the response box' => 'Activer le téléchargement de fichiers dans la zone de réponse',
  'Enable Google reCAPTCHA in the response box' => 'Activez Google reCAPTCHA dans la zone de réponse',
  'Enable download button in the response box' => 'Activer le bouton de téléchargement dans la zone de réponse',
  'Display the IP addresses of users in the response box.' => 'Affichez les adresses IP des utilisateurs dans la zone de réponse.',
  'Persia Payment Add-on' => 'Module complémentaire de paiement Persia',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => 'Le module complémentaire de paiement Persia pour Flux Forms vous permet de connecter votre site Web à Persia Payment pour traiter les paiements, les dons et les commandes en ligne.',
  'Jalali Date Add-on' => 'Module complémentaire de date Jalali',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => 'Le module complémentaire Jalali Date vous permet d\'ajouter un champ de date Jalali à vos formulaires et de créer tout type de formulaire incluant ce champ de date Shamsi.',
  'Hijri Date Add-on' => 'Module complémentaire Date Hijri',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => 'Le module complémentaire Hijri Date vous permet d\'ajouter un champ de date Hijri à vos formulaires et de créer tout type de formulaire incluant ce champ.',
  'SMS service Add-on' => 'Module complémentaire de service SMS',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => 'Le module complémentaire du service SMS vous permet de recevoir des messages SMS de notification lorsque vous ou vos clients recevez de nouveaux messages ou réponses.',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => 'Veuillez installer le module complémentaire de date Hijri ou Jalali. Vous ne pouvez pas installer les deux modules complémentaires simultanément.',
  'Response box' => 'Boîte de réponse',
  'Regions Drop-Down' => 'liste déroulante des régions',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => 'Vous voyez ce message car les modules complémentaires requis sont en cours d\'installation. Veuillez patienter quelques minutes, puis visiter à nouveau cette page. Si plus de cinq minutes se sont écoulées et que rien ne s\'est produit, veuillez contacter l\'équipe d\'assistance de Flux Forms sur Whitestudio.team.',
  'The cell phone number is incorrect' => 'Le numéro de téléphone portable est incorrect',
  'Invalid country code' => 'Code pays invalide',
  'The cell phone number is too short' => 'Le numéro de téléphone portable est trop court',
  'The cell phone number is too long' => 'Le numéro de téléphone portable est trop long',
