  'Disabled Field' => 'Champ désactivé',
  'Hidden Field' => 'Champ caché',
  'Select a country to display a list of states/provinces.' => 'Sélectionnez un pays pour afficher une liste d\'états/provinces.',
  'Select a state/province to display a list of cities.' => 'Sélectionnez un état/une province pour afficher une liste de villes.',
  'SMS Service Add-on' => 'Module complémentaire de service SMS',
  'This field is currently unavailable. Please contact the site administrator.' => 'Ce champ est actuellement indisponible. Veuillez contacter l\'administrateur du site.',
  'Would you like to customize the form using the colors of the active template?' => 'Voulez-vous personnaliser le formulaire en utilisant les couleurs du modèle actif ?',
  'Flux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.' => 'Flux Forms a utilisé les couleurs du modèle actif. Veuillez choisir une couleur pour chaque option ci-dessous afin de personnaliser le formulaire que vous créez en fonction des couleurs de votre modèle. En sélectionnant une couleur pour chaque option ci-dessous, la couleur de tous les champs de formulaire associés à cette fonctionnalité changera en conséquence.',
  'Buttons text colors' => 'Couleurs du texte des boutons',
  'attached files' => 'fichiers joints',
  'Default selected' => 'Sélectionné par défaut',
  'Show attributes' => 'Afficher les attributs',
  'Hide attributes' => 'Masquer les attributs',
  'The ID length should be at least 3 characters long.' => 'La longueur de l\'ID doit comporter au moins 3 caractères.',
  'The ID value must be unique, as it is already being used in this field. Please try a new, unique value.' => 'La valeur de l\'ID doit être unique, car elle est déjà utilisée dans ce champ. Veuillez essayer une nouvelle valeur unique.',
  'Image picker' => 'Sélecteur d\'images',
  'Insert an image url' => 'Insérer une URL d\'image',
  'New Booking Form' => 'Nouveau formulaire de réservation',
  'Conditional Logic Add-on' => 'Module complémentaire de logique conditionnelle',
  'Conditional logic Add-on' => 'Module complémentaire de logique conditionnelle',
  'The Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.' => 'Le module complémentaire Conditional Logic permet d\'activer des formulaires dynamiques et interactifs basés sur des entrées utilisateur spécifiques ou des règles conditionnelles. Il permet de créer des formulaires hautement personnalisés adaptés pour répondre aux besoins uniques des utilisateurs.',
  'The Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.' => 'Le module de logique conditionnelle n\'a pas pu être chargé. Veuillez actualiser la page ; si le problème persiste, désactivez et réactivez le module complémentaire Conditional Logic.',
  'Stop after this rule matches' => 'Arrêtez après que cette règle corresponde',
  'IF' => 'SI',
  'THEN' => 'ALORS',
  'Test Mode' => 'Mode Test',
  'Run Test' => 'Exécuter le test',
