  'Not matched' => 'Ne correspond pas',
  'No fields found.' => 'Aucun champ trouvé.',
  'You can create up to %1$s %2$s on your current plan. Upgrade to Pro for unlimited access.' => 'Vous pouvez créer jusqu\'à %1$s%2$s sur votre forfait actuel. Passez à Pro pour un accès illimité.',
  'Inspector' => 'Inspecteur',
  'Rule trace' => 'Trace de règle',
  'Final values' => 'Valeurs finales',
  'Effects' => 'Effets',
