  'Error: Please ensure there is only one form per page.' => 'Erreur : Veuillez vous assurer qu\'il n\'y a qu\'un seul formulaire par page.',
  'Your activation code has been verified. Enjoy all Pro features of Flux Forms.' => 'Votre code d\'activation a été vérifié. Profitez de toutes les fonctionnalités Pro de Flux Forms.',
  'The confirmation code for this message is %s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => 'Le code de confirmation de ce message est %s. En cliquant sur le bouton ci-dessous, vous pourrez suivre les messages et afficher les réponses reçues. Si nécessaire, vous pouvez également envoyer une nouvelle réponse.',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our %1$s documentation %2$s .' => 'Pour explorer toutes les fonctionnalités et paramètres de Flux Forms, y compris les configurations de messagerie, les options de création de formulaires et d\'autres fonctionnalités, plongez simplement dans notre documentation %1$s%2$s.',
  'Responses & Confirmation' => 'Réponses et confirmation',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings %1$sLearn how to fix email delivery issues%2$s or %3$scontact Flux Forms support%4$s.' => 'Les e-mails de test peuvent atterrir dans votre dossier spam. Si les e-mails ne sont pas livrés, cela est généralement lié à la configuration de votre hébergement ou de votre serveur de messagerie. Paramètres du serveur %1$sDécouvrez comment résoudre les problèmes de livraison des e-mails%2$s ou %3$scontactez l\'assistance Flux Forms%4$s.',
  'From Address' => 'Adresse d\'origine',
