  'The map library (OpenStreetMap and Leaflet) loads only on pages that contain a location picker field.' => 'La bibliothèque de cartes (OpenStreetMap et Leaflet) se charge uniquement sur les pages contenant un champ de sélection d\'emplacement.',
  'Enable Location Picker in Flux Forms' => 'Activer le sélecteur d\'emplacement dans Flux Forms',
