  'verify' => 'vérifier',
  'The form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".' => 'Le formulaire ne peut pas être soumis car il nécessite un mode de paiement, qui est actuellement manquant. Si vous êtes l\'administrateur, veuillez ajouter un mode de paiement au formulaire ou modifier le type de formulaire en "Formulaire" ou "Enquête".',
  'Cache Plugin Detected' => 'Plug-in de cache détecté',
  'The following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.' => 'Les plugins de cache suivants peuvent interférer avec la fonctionnalité du formulaire. Si vous rencontrez des problèmes, veuillez consulter la documentation.',
  'Read more about cache compatibility' => 'En savoir plus sur la compatibilité du cache',
  'Dismiss All' => 'Tout ignorer',
  'Dismiss %s' => 'Ignorer %s',
  'Security Plugin Detected' => 'Plug-in de sécurité détecté',
  'The following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.' => 'Le plugin de sécurité suivant peut bloquer les soumissions de formulaires contenant des erreurs 403. Il peut bloquer l\'API REST, supprimer l\'en-tête X-WP-Nonce ou appliquer des règles de pare-feu aux requêtes de formulaire.',
  'Read more about security plugin compatibility' => 'En savoir plus sur la compatibilité des plugins de sécurité',
  'Auto-Populate Add-on' => 'Module complémentaire de remplissage automatique',
  'The Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.' => 'Le module complémentaire Auto-Populate vous permet de remplir automatiquement les champs de formulaire à partir d\'ensembles de données, de formulaires précédemment soumis ou d\'API externes.',
  'Form Security & Spam Protection' => 'Sécurité des formulaires et protection anti-spam',
  'Behavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.' => 'Protection anti-spam et anti-abus d\'API basée sur le comportement avec des limites de débit et un stop-loss pour les notifications payantes telles que les SMS, les télégrammes, les e-mails et les webhooks.',
  'Google Sheet Add-on' => 'Module complémentaire Google Sheet',
  'Automatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.' => 'Envoyez automatiquement les soumissions de formulaires à vos feuilles de calcul Google en temps réel. Connectez un compte de service, mappez les champs aux colonnes et conservez une feuille de calcul stylisée et dynamique de chaque réponse : aucun webhook ou connexion au navigateur n\'est requis.',
  'Please fill in all required fields' => 'Veuillez remplir tous les champs obligatoires',
  'Email Server Status' => 'État du serveur de messagerie',
  'The test email never arrived' => 'L\'e-mail de test n\'est jamais arrivé',
  'Your WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.' => 'Votre site WordPress ne peut pas envoyer d\'e-mails de manière fiable. Il s\'agit d\'un problème d\'hébergement très courant : la fonction de messagerie PHP par défaut est souvent bloquée ou finit dans le spam. L\'installation d\'un plug-in SMTP achemine vos e-mails via un service de messagerie vérifié et résout ce problème en quelques minutes.',
  'WordPress sent the email - it just never arrived' => 'WordPress a envoyé l\'e-mail - il n\'est tout simplement jamais arrivé',
  'Your site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'Votre site a transmis le message à votre serveur de messagerie avec succès, donc WordPress et ce plugin ont fait leur part. Il a été perdu, retardé ou rejeté par la suite - le plus souvent, la boîte aux lettres de réception l\'a classé comme spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante. L\'envoi via un service SMTP, avec des enregistrements SPF et DKIM pour votre domaine, est ce qui résout ce problème.',
  'WordPress could not send the email' => 'WordPress n\'a pas pu envoyer l\'e-mail',
  'The message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.' => 'Le message n\'a jamais quitté votre site Web : WordPress a renvoyé une erreur lors de son envoi. Installez et configurez un plugin SMTP, ou demandez à votre hébergeur si la messagerie PHP est désactivée.',
  'Your emails arrive, but will most likely land in spam' => 'Vos e-mails arrivent, mais atterriront très probablement dans les spams',
  'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.' => 'La livraison elle-même fonctionne - le message de test nous est parvenu. Ce qui manque, c\'est la confiance : l\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine sont ce qui déplace vos e-mails du dossier spam vers la boîte de réception.',
  'The test email was delivered with a deliverability score of %1$s out of 100. Under %2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.' => 'L\'e-mail de test a été envoyé avec un score de délivrabilité de %1$s sur 100. Sous %2$s, la plupart des boîtes aux lettres classent les messages dans le dossier spam, de sorte que les personnes qui remplissent vos formulaires risquent de ne jamais les voir.',
  'Step-by-step SMTP setup guide' => 'Guide de configuration SMTP étape par étape',
  'Your email server is working. A detailed HTML report has been sent to %s.' => 'Votre serveur de messagerie fonctionne. Un rapport HTML détaillé a été envoyé à %s.',
  'your admin email address' => 'votre adresse e-mail d\'administrateur',
  'Spam Score Report on the Way!' => 'Rapport sur le score de spam en route !',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to %s within the next few minutes.' => 'Un rapport complet sur l\'état des e-mails (incluant votre score de spam, les détails de délivrabilité et les recommandations) sera envoyé à %s dans les prochaines minutes.',
  'Email notifications may not be delivered' => 'Les notifications par e-mail peuvent ne pas être envoyées',
  'This form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is %s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.' => 'La fonctionnalité de notification par e-mail de ce formulaire est activée, mais la livraison des e-mails n\'a pas été vérifiée et le dernier score de spam est %s/100. Le formulaire a été enregistré, mais les e-mails de notification de l\'administrateur risquent de ne pas vous parvenir tant que la livraison SMTP/e-mail n\'est pas corrigée.',
  'Notification emails are turned off' => 'Les e-mails de notification sont désactivés',
  'Flux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.' => 'Flux Forms n\'enverra aucun e-mail — ni à vous ni à la personne qui soumet ce formulaire — jusqu\'à ce que « Ce site peut envoyer des e-mails » soit activé dans les paramètres de messagerie.',
  'Enable email sending' => 'Activer l\'envoi d\'e-mails',
  'Click "Check Email Server" to test delivery, turn this switch on, then press Save.' => 'Cliquez sur "Vérifier le serveur de messagerie" pour tester la livraison, activez ce commutateur, puis appuyez sur Enregistrer.',
  'Delivery is taking longer than expected' => 'La livraison prend plus de temps que prévu',
  'WordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.' => 'WordPress a envoyé l\'e-mail de test, mais notre serveur ne l\'a pas encore reçu. Il peut s\'agir d\'un retard temporaire. Vérifiez les diagnostics ci-dessous pour résoudre les problèmes.',
  'Prepare Test' => 'Préparer le test',
  'Connecting to WhiteStudio to generate a unique test email address.' => 'Connexion à WhiteStudio pour générer une adresse e-mail de test unique.',
  'WordPress Sends the Email' => 'WordPress envoie l\'e-mail',
  'WordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.' => 'WordPress transmet un vrai message à votre serveur de messagerie. Une coche ici signifie que WordPress l\'a envoyé, mais qu\'il n\'est pas encore arrivé.',
  'Waiting for Delivery' => 'En attente de livraison',
  'Checking whether the test email arrived at our server (usually takes a few seconds).' => 'Vérifier si l\'e-mail de test est arrivé sur notre serveur (cela prend généralement quelques secondes).',
  'Quick Result' => 'Résultat rapide',
  'Showing the first delivery result — you will see right away if email is working.' => 'Affichage du premier résultat de livraison : vous verrez immédiatement si le courrier électronique fonctionne.',
  'Full Report' => 'Rapport complet',
  'A detailed HTML report with full diagnostics is being prepared and emailed to you.' => 'Un rapport HTML détaillé avec des diagnostics complets est en cours de préparation et vous est envoyé par courrier électronique.',
  'Needs attention' => 'Besoin d\'attention',
  '%s of 5 steps done' => ' %s étapes sur 5 effectuées',
  'Step %s of 5' => 'Étape %s sur 5',
  '/ 100' => '/ 100',
  'Test started' => 'Test démarré',
  'A unique address is being generated for this test.' => 'Une adresse unique est générée pour ce test.',
  'Waiting for the email to arrive' => 'En attente de l\'arrivée de l\'e-mail',
  'We check our server every few seconds. Please keep this page open.' => 'Nous vérifions notre serveur toutes les quelques secondes. Veuillez garder cette page ouverte.',
  'Your email server is healthy' => 'Votre serveur de messagerie est sain',
  'The test email arrived, and the subject and unique-code checks both passed.' => 'L\'e-mail de test est arrivé et les vérifications de l\'objet et du code unique ont toutes deux réussi.',
  'Delivered, but likely to be filtered as spam' => 'Livré, mais susceptible d\'être filtré comme spam',
  'Delivered, but deliverability is weak' => 'Livré, mais la délivrabilité est faible',
  'No email arrived' => 'Aucun e-mail n\'est arrivé',
  'Nothing was received during the test window, so your server most likely cannot send email.' => 'Rien n\'a été reçu pendant la fenêtre de test, votre serveur ne pourra donc probablement pas envoyer d\'e-mails.',
  'The test timed out' => 'Le test a expiré',
  'The test reached its time limit. Your server may be slow, or may block outbound email.' => 'Le test a atteint sa limite de temps. Votre serveur peut être lent ou bloquer les e-mails sortants.',
  'The test email could not be sent' => 'L\'e-mail de test n\'a pas pu être envoyé',
  'WordPress returned an error while sending. See the message below.' => 'WordPress a renvoyé une erreur lors de l\'envoi. Consultez le message ci-dessous.',
  'The connection was lost' => 'La connexion a été perdue',
  'No answer came back from the server. Refresh the page and try again.' => 'Aucune réponse n\'est revenue du serveur. Actualisez la page et réessayez.',
  'This test needs a higher plan' => 'Ce test nécessite un plan supérieur',
  'Upgrade your plan to run the full delivery test.' => 'Mettez à niveau votre plan pour exécuter le test de livraison complet.',
  'Your email server is working. A detailed HTML report has been sent to' => 'Votre serveur de messagerie fonctionne. Un rapport HTML détaillé a été envoyé à',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to' => 'Un rapport complet sur l\'état de santé des e-mails (incluant votre score de spam, les détails de délivrabilité et les recommandations) sera envoyé dans les prochaines minutes à',
  'Upgrade required' => 'Mise à niveau requise',
