  'Score: %s' => 'Score : %s',
  'Upgrade' => 'Mise à niveau',
  'The test timed out. Please try again — your server may be slow or blocking outgoing mail.' => 'Le test a expiré. Veuillez réessayer : votre serveur est peut-être lent ou bloque le courrier sortant.',
  'Waiting for the test email to arrive…' => 'En attente de l\'arrivée de l\'e-mail de test...',
