  'Your subscription needs renewing before the missing add-ons can be restored.' => 'Votre abonnement doit être renouvelé avant que les modules complémentaires manquants puissent être restaurés.',
  'The missing add-on files could not be restored. Check the server connection and file permissions, then try again.' => 'Les fichiers complémentaires manquants n\'ont pas pu être restaurés. Vérifiez la connexion au serveur et les autorisations de fichiers, puis réessayez.',
  'You do not have permission to do this.' => 'Vous n\'êtes pas autorisé à faire cela.',
  'All required add-ons were restored.' => 'Tous les modules complémentaires requis ont été restaurés.',
  'Finish updating Flux Forms' => 'Terminer la mise à jour de Flux Forms',
  'Some add-on files are missing' => 'Certains fichiers complémentaires sont manquants',
  'The plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.' => 'Le plugin a été mis à jour, ses modules complémentaires doivent donc être réinstallés avant que cette page puisse se charger. Cliquez sur le bouton ci-dessous pour les installer.',
  'One or more add-on files are missing. Click the button below to reinstall them.' => 'Un ou plusieurs fichiers complémentaires sont manquants. Cliquez sur le bouton ci-dessous pour les réinstaller.',
  'Automatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.' => 'La récupération automatique a été tentée mais n\'a pas abouti. Examinez la raison ci-dessous, corrigez-la si nécessaire, puis réessayez.',
  'Recover add-ons' => 'Récupérer les modules complémentaires',
  'Installing add-ons…' => 'Installation de modules complémentaires...',
  'Installation complete.' => 'Installation terminée.',
  'Click to activate the add-ons.' => 'Cliquez pour activer les modules complémentaires.',
  'Activate add-ons' => 'Activer les modules complémentaires',
  'Installation failed. Please try again.' => 'L\'installation a échoué. Veuillez réessayer.',
  'Missing add-ons:' => 'Modules complémentaires manquants :',
  'Why the recovery failed' => 'Pourquoi la récupération a échoué',
  'Preparing your form' => 'Préparer votre formulaire',
  'Add-ons restored successfully' => 'Modules complémentaires restaurés avec succès',
  'The form is being prepared. This page will reload automatically.' => 'Le formulaire est en cours de préparation. Cette page se rechargera automatiquement.',
  'The page will reload automatically so the restored add-ons can be activated.' => 'La page se rechargera automatiquement afin que les modules complémentaires restaurés puissent être activés.',
  'Reload now' => 'Recharger maintenant',
  'This form is temporarily unavailable.' => 'Ce formulaire est temporairement indisponible.',
  'We could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.' => 'Nous n\'avons pas pu restaurer automatiquement un composant de formulaire requis. Veuillez réessayer sous peu ; l\'administrateur du site peut afficher l\'erreur de récupération exacte dans Flux Forms.',
  'The add-on is already installed.' => 'Le module complémentaire est déjà installé.',
  'File access status not checked yet. Please wait.' => 'L\'état d\'accès au fichier n\'est pas encore vérifié. Veuillez patienter.',
  'Error: server (%s) responded with an invalid request. responded code: %s' => 'Erreur : le serveur (%s) a répondu avec une requête non valide. code répondu : %s',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the %s server' => 'Impossible d\'installer les modules complémentaires de Flux Forms car le plugin ne parvient pas à se connecter au serveur %s',
  'Your Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:' => 'Votre abonnement Easy Form Builder Pro a expiré, les modules complémentaires Pro n\'ont donc pas pu être téléchargés. Le plugin continue de fonctionner sans eux. Renouvelez votre abonnement pour restaurer toutes les fonctionnalités Pro :',
  'The version of the add-on is not compatible with the version of the Flux Forms plugin.' => 'La version du module complémentaire n\'est pas compatible avec la version du plugin Flux Forms.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to download files' => 'Impossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas en mesure de télécharger des fichiers',
  'Cannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.' => 'Impossible d\'installer des modules complémentaires car ce serveur a désactivé les fonctions du système de fichiers PHP nécessaires à la préparation du téléchargement. Veuillez demander à votre fournisseur d\'hébergement d\'activer mkdir et de le renommer, ou de configurer le système de fichiers WordPress.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file' => 'Impossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas en mesure de déplacer le fichier téléchargé',
  'Cannot install add-ons of Flux Forms because the plugin is not able to unzip files' => 'Impossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas capable de décompresser les fichiers',
  'To fix this, sign in to your %s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.' => 'Pour résoudre ce problème, connectez-vous à votre %s, téléchargez le plug-in Add-ons Handler depuis la section Téléchargements, puis installez-le et activez-le. Après cela, activez les modules complémentaires dont vous avez besoin à partir du plug-in Add-ons Handler.',
  'WhiteStudio dashboard' => 'Tableau de bord WhiteStudio',
  'This bundled add-on is missing from the plugin files.' => 'Ce module complémentaire fourni est absent des fichiers du plugin.',
  'The add-on server returned an unexpected response.' => 'Le serveur de module complémentaire a renvoyé une réponse inattendue.',
  'The add-on could not be installed.' => 'Le module complémentaire n\'a pas pu être installé.',
  'The add-on server did not provide a download URL.' => 'Le serveur du module complémentaire n\'a pas fourni d\'URL de téléchargement.',
  'The add-on download URL is not an approved Flux Forms source.' => 'L\'URL de téléchargement du module complémentaire n\'est pas une source Flux Forms approuvée.',
  'Your server could not reach %1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at %2$s and download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.' => 'Votre serveur n\'a pas pu atteindre %1$s, le module complémentaire n\'a donc pas pu être téléchargé. Il s\'agit presque toujours d\'un pare-feu sur votre hébergement bloquant la requête sortante, et non d\'un problème avec votre licence. Pour installer des modules complémentaires sans aucun téléchargement, connectez-vous sur %2$s et téléchargez le plugin Flux Forms Add-ons Handler, puis installez-le comme n\'importe quel autre plugin. Il contient tous les modules complémentaires couverts par votre licence.',
  'If you would rather fix the connection, ask your hosting provider why outgoing requests from %s are being blocked.' => 'Si vous préférez réparer la connexion, demandez à votre fournisseur d\'hébergement pourquoi les requêtes sortantes de %s sont bloquées.',
  'Flux Forms: add-on downloads are being blocked' => 'Flux Forms : les téléchargements de modules complémentaires sont bloqués',
  'Add-on affected: %s' => 'Module complémentaire concerné : %s',
  'No response was recorded for this add-on.' => 'Aucune réponse n\'a été enregistrée pour ce module complémentaire.',
  'Writable' => 'Inscriptible',
  'Not writable — the add-on folder cannot be created or extracted into.' => 'Non accessible en écriture : le dossier du module complémentaire ne peut pas être créé ou extrait.',
  'Blocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.' => 'Bloqué par WP_HTTP_BLOCK_EXTERNAL — les requêtes sortantes sont désactivées sur ce site.',
  'DISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.' => 'DISABLE_WP_CRON est activé : les tentatives en arrière-plan ne s\'exécutent que si une tâche périodique du serveur appelle wp-cron.php.',
  'Page that needed it' => 'Page qui en avait besoin',
  'Plugin version' => 'Version du plugin',
  'Add-on folder' => 'Dossier de modules complémentaires',
  'Outgoing requests' => 'Demandes sortantes',
  'WP-Cron' => 'WP-Cron',
  'Attempts made' => 'Tentatives effectuées',
  'Flux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.' => 'Flux Forms n\'a pas pu réinstaller automatiquement ses fichiers complémentaires. Les formulaires qui s\'appuient sur ces modules complémentaires affichent un message temporaire aux visiteurs jusqu\'à ce que le problème soit résolu.',
  'What is missing' => 'Ce qui manque',
  'Diagnostics' => 'Diagnostics',
  'What to do next' => 'Que faire ensuite',
  'Open Flux Forms in your dashboard and use the Recover add-ons button.' => 'Ouvrez Flux Forms dans votre tableau de bord et utilisez le bouton Récupérer les modules complémentaires.',
  'If the add-on folder is not writable, ask your host to allow writing to the plugin folder.' => 'Si le dossier du module complémentaire n\'est pas accessible en écriture, demandez à votre hébergeur d\'autoriser l\'écriture dans le dossier du plugin.',
  'If outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.' => 'Si les requêtes sortantes sont bloquées, demandez à votre hébergeur d\'autoriser les connexions au serveur de mise à jour de Flux Forms.',
  'If your Pro subscription has expired, renew it to restore the Pro add-ons.' => 'Si votre abonnement Pro a expiré, renouvelez-le pour restaurer les modules complémentaires Pro.',
  'We have made some updates. Please wait a few minutes before trying again.' => 'Nous avons effectué quelques mises à jour. Veuillez patienter quelques minutes avant de réessayer.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server' => 'Impossible d\'installer les modules complémentaires de Flux Forms car le plugin ne parvient pas à se connecter au serveur whitestudio.team',
  'One of the free features' => 'Une des fonctionnalités gratuites',
  'Important: Caching Plugin May Affect Flux Forms' => 'Important : Le plugin de mise en cache peut affecter les formulaires de flux',
  'The following caching plugins are active on your site:' => 'Les plugins de mise en cache suivants sont actifs sur votre site :',
  'Plugin Name' => 'Nom du plugin',
  'Slug' => 'Limace',
  'Please note that these plugins may affect the functionality of Flux Forms.' => 'Veuillez noter que ces plugins peuvent affecter les fonctionnalités de Flux Forms.',
  'If you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.' => 'Si vous rencontrez des problèmes, veuillez exclure de la mise en cache la page sur laquelle votre formulaire est publié ou désactiver ces plugins. Pour obtenir des conseils détaillés sur la façon de configurer cette exclusion, veuillez vous référer à la documentation du plug-in de mise en cache concerné.',
  'Sent by' => 'Envoyé par',
  'Action needed: Flux Forms Pro is paused on %s' => 'Action nécessaire : Flux Forms Pro est en pause le %s',
  'Flux Forms could not confirm your Pro licence for %1$s days in a row, so the Pro features on %2$s are paused for now.' => 'Flux Forms n\'a pas pu confirmer votre licence Pro pendant %1$s jours consécutifs, les fonctionnalités Pro sur %2$s sont donc suspendues pour le moment.',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored &mdash; nothing was deleted.' => 'Vos formulaires, entrées et paramètres restent intacts, toutes les fonctionnalités gratuites continuent de fonctionner et votre code d\'activation est toujours stocké – rien n\'a été supprimé.',
  'Open %1$sYT Form &rarr; Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'Ouvrez %1$sYT Form → Paramètres%2$s et appuyez sur %1$sEnregistrer%2$s. Cela vérifie à nouveau la licence immédiatement ; si la connexion est rétablie, Pro s\'allume dans la minute.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s &mdash; a firewall, proxy or regional block is the usual cause &mdash; then repeat step 1.' => 'Toujours en pause ? Demandez à votre fournisseur d\'hébergement d\'autoriser les connexions HTTPS sortantes vers %s(un pare-feu, un proxy ou un blocage régional est la cause habituelle), puis répétez l\'étape 1.',
  'If your subscription has expired, or you moved this website to a new domain, %1$srenew or re-activate your licence%2$s and paste the new code into Settings.' => 'Si votre abonnement a expiré ou si vous avez déplacé ce site Web vers un nouveau domaine, %1$srenouvellez ou réactivez votre licence%2$s et collez le nouveau code dans Paramètres.',
  'First failed check' => 'Premier contrôle échoué',
  'Grace period' => 'délai de grâce',
  'Activation code' => 'Code d\'activation',
  'Error code' => 'Code d\'erreur',
  'How to bring Pro back' => 'Comment ramener Pro',
  'Check my licence now' => 'Vérifiez ma licence maintenant',
  'Still stuck? Send the details above to %1$sour support team%2$s and we will take it from there.' => 'Toujours bloqué ? Envoyez les détails ci-dessus à %1$snotre équipe d\'assistance%2$s et nous nous occuperons de là.',
  'The licence server answered with an error and could not confirm your licence.' => 'Le serveur de licences a répondu avec une erreur et n\'a pas pu confirmer votre licence.',
  'Your website could not reach the licence server &mdash; almost always a network, firewall or DNS restriction on the hosting side.' => 'Votre site Web n\'a pas pu atteindre le serveur de licences – presque toujours à cause d\'une restriction réseau, pare-feu ou DNS du côté de l\'hébergement.',
  'The licence server&rsquo;s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'La réponse du serveur de licences est arrivée endommagée, généralement parce qu\'un plugin de sécurité, un proxy ou un CDN l\'a modifiée en cours de route.',
  'The licence check could not be completed.' => 'La vérification de la licence n\'a pas pu être effectuée.',
  'Your activation code has expired!' => 'Votre code d\'activation a expiré !',
  'Your Easy Form Builder Pro subscription has expired. To continue using the %s add-on and all Pro features, please renew your subscription.' => 'Votre abonnement Easy Form Builder Pro a expiré. Pour continuer à utiliser le module complémentaire %s et toutes les fonctionnalités Pro, veuillez renouveler votre abonnement.',
  'Renew Subscription' => 'Renouveler l\'abonnement',
  'Pro Version Required' => 'Version Pro requise',
  'The %s add-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.' => 'Le module complémentaire %s est une fonctionnalité Pro. Veuillez effectuer une mise à niveau vers Flux Forms Pro pour accéder à cette fonctionnalité.',
  'Your Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running, %1$sRenew your subscription now.%2$s' => 'Votre abonnement Easy Form Builder Pro a expiré. Pour continuer à profiter de toutes les fonctionnalités Pro et maintenir vos formulaires opérationnels, %1$s Renouvelez votre abonnement maintenant. %2$s ',
  'The payment could not be verified yet.' => 'Le paiement n\'a pas encore pu être vérifié.',
  'This payment provider does not support refunds from the site.' => 'Ce fournisseur de paiement ne prend pas en charge les remboursements à partir du site.',
  'Trial' => 'Essai',
  'Canceled' => 'Annulé',
  'Amount mismatch' => 'Incohérence de montant',
  'Unpaid' => 'Impayé',
  'Incomplete' => 'Incomplet',
  'Expired' => 'Expiré',
  'Sorry, you are not allowed to access this page.' => 'Désolé, vous n\'êtes pas autorisé à accéder à cette page.',
  'Payments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.' => 'Paiements effectués via vos formulaires, auprès de chaque fournisseur de paiement. Les clés API et le fournisseur actif sont définis sur la page Paramètres du plugin, onglet Paiement.',
  'A Stripe webhook signing secret starts with "whsec_".' => 'Un secret de signature de webhook Stripe commence par "whsec_".',
  'Providers and webhooks' => 'Fournisseurs et webhooks',
  'Configured' => 'Configuré',
  'Not configured' => 'Non configuré',
  'Webhook URL for this provider (if it sends payment notifications):' => 'URL du Webhook pour ce fournisseur (s\'il envoie des notifications de paiement) :',
  'Recent payments' => 'Paiements récents',
  'No payments yet.' => 'Aucun paiement pour l\'instant.',
  'Confirmation code' => 'Code de confirmation',
  'Transaction ID' => 'ID de transaction',
  'Subscription' => 'Abonnement',
  'One-time' => 'Une seule fois',
  'The latest %d payments are shown.' => 'Les derniers paiements %d sont affichés.',
  'Test provider (development only)' => 'Fournisseur de tests (développement uniquement)',
  'Test outcome' => 'Résultat du test',
  'Approve every payment' => 'Approuver chaque paiement',
  'Decline every payment' => 'Refuser tout paiement',
  'No money is taken. Development only.' => 'Aucun argent n\'est prélevé. Développement uniquement.',
  'TEST MODE: no card is charged.' => 'MODE TEST : aucune carte n\'est débitée.',
  'Test provider: the payment was declined.' => 'Fournisseur de test : le paiement a été refusé.',
  'Publishable key' => 'Clé publiable',
  'Stripe is not configured on this site. Please contact the site administrator.' => 'Stripe n\'est pas configuré sur ce site. Veuillez contacter l\'administrateur du site.',
  'The payment method of this form is not supported.' => 'Le mode de paiement de ce formulaire n\'est pas pris en charge.',
  'The payment could not be started. Please try again.' => 'Le paiement n\'a pas pu démarrer. Veuillez réessayer.',
  'Optional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.' => 'Facultatif mais recommandé : dans le tableau de bord Stripe, ajoutez un point de terminaison webhook avec cette URL et les événements payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated et customer.subscription.deleted, puis collez son secret de signature ci-dessous.',
  'Webhook signing secret' => 'Secret de signature du Webhook',
  'Saved - leave empty to keep it' => 'Enregistré - laissez vide pour le conserver',
  'Remove the saved secret' => 'Supprimer le secret enregistré',
  'Invalid or expired nonce' => 'Nonce non valide ou expiré',
  'No payment provider is available on this site. Please contact the site administrator.' => 'Aucun prestataire de paiement n\'est disponible sur ce site. Veuillez contacter l\'administrateur du site.',
  'Too many payment attempts. Please wait a few minutes and try again.' => 'Trop de tentatives de paiement. Veuillez patienter quelques minutes et réessayer.',
  'Invalid payment data. Please refresh the page and try again.' => 'Données de paiement invalides. Veuillez actualiser la page et réessayer.',
  'The payment provider is not configured on this site. Please contact the site administrator.' => 'Le prestataire de paiement n\'est pas configuré sur ce site. Veuillez contacter l\'administrateur du site.',
  'No payment amount detected. Please review your selected items and try again. If the problem persists, contact support.' => 'Aucun montant de paiement détecté. Veuillez vérifier les éléments sélectionnés et réessayer. Si le problème persiste, contactez l\'assistance.',
  'Too many requests. Please wait a moment and try again.' => 'Trop de demandes. Veuillez patienter un moment et réessayer.',
  'Payment not found.' => 'Paiement introuvable.',
  'Your payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'Votre paiement n\'a pas encore été confirmé. Veuillez patienter un moment et réessayer. Si le problème persiste, contactez l\'administrateur du site.',
  'Online payment is not available at the moment. Please try again later or contact us.' => 'Le paiement en ligne n\'est pas disponible pour le moment. Veuillez réessayer plus tard ou contactez-nous.',
  'Active payment provider' => 'Fournisseur de paiement actif',
  'Payment forms take card payments through this provider. Only installed providers are listed.' => 'Les formulaires de paiement acceptent les paiements par carte via ce fournisseur. Seuls les fournisseurs installés sont répertoriés.',
  'Saved — leave empty to keep' => 'Enregistré — laissez vide pour conserver',
  '%s settings' => ' Paramètres %s',
  'Flux Forms replaces %s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.' => 'Flux Forms remplace %s, qui a été désactivé. Vos formulaires, entrées et paramètres restent en place. Vous pouvez supprimer l\'ancien plugin.',
  'Updating amount…' => 'Mise à jour du montant...',
  'The amount could not be verified. Please check your selections and try again.' => 'Le montant n\'a pas pu être vérifié. Veuillez vérifier vos sélections et réessayer.',
  'Subject made by Flux Forms (with the tracking code)' => 'Sujet réalisé par Flux Forms (avec le code de suivi)',
  'Message: tracking code and submitted values (HTML)' => 'Message : code de suivi et valeurs soumises (HTML)',
  'Link to the message / response page' => 'Lien vers la page message/réponse',
  'User name (registration, password recovery)' => 'Nom d\'utilisateur (enregistrement, récupération de mot de passe)',
  'We have received your message' => 'Nous avons reçu votre message',
  'New form message' => 'Nouveau message du formulaire',
  'Sent to the form\'s notification addresses when a form is filled in or a message gets a new reply.' => 'Envoyé aux adresses de notification du formulaire lorsqu\'un formulaire est rempli ou qu\'un message reçoit une nouvelle réponse.',
  'New message' => 'Nouveau message',
