  'File upload budget' => 'Budget de téléchargement de fichiers',
  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => 'Flux Forms limite déjà les téléchargements : chaque visiteur peut télécharger trois fichiers par champ de fichier sur le formulaire, et la zone de réponse en autorise trois. Laissez une case à 0 pour conserver ce comportement automatique, ou entrez un nombre pour le définir vous-même.',
  'Uploads allowed per file field' => 'Téléchargements autorisés par champ de fichier',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => 'Par défaut 3, donc un formulaire à deux champs autorise six téléchargements. 0 conserve la valeur par défaut.',
  'Total uploads per visitor' => 'Total des téléchargements par visiteur',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => 'Un total fixe qui ignore le nombre de champs du formulaire. 0 conserve le calcul automatique par champ.',
  'Budget resets after (seconds)' => 'Le budget est réinitialisé après (secondes)',
  'Default 3600 (one hour). 0 keeps the default.' => 'Par défaut 3 600 (une heure). 0 conserve la valeur par défaut.',
  'Maximum file size (MB)' => 'Taille maximale du fichier (Mo)',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => 'Un plafond à l\'échelle du site. Il ne peut que resserrer une limite par champ, jamais l\'élargir. 0 conserve le paramètre du champ.',
  'Protect response lookup' => 'Protéger la recherche de réponse',
  'Rate-limit tracking-code searches by request count (no human-token check).' => 'Recherches de code de suivi avec limite de débit par nombre de requêtes (pas de vérification de jeton humain).',
  'Manual access lists' => 'Listes d\'accès manuel',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => 'Une entrée par ligne : une adresse IP exacte ou un préfixe générique tel que 203.0.113.* — la liste autorisée contourne toutes les vérifications, la liste de blocage bloque dans tous les modes.',
  'IP allowlist' => 'Liste d\'adresses IP autorisées',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => 'IPs de confiance qui ignorent complètement le bouclier (votre bureau, surveillance des robots).',
  'IP blocklist' => 'Liste de blocage des adresses IP',
