  'Client attestation timeout' => 'Délai d\'expiration de l\'attestation client',
  'Milliseconds before the browser falls back to the normal request.' => 'Millisecondes avant que le navigateur ne revienne à la requête normale.',
  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => 'Si une fonction PHP requise est désactivée, activez-la dans php.ini Disable_functions ou demandez à l\'hôte de l\'autoriser. Les plugins de cache et de sécurité ne doivent pas mettre en cache ou réécrire les réponses POST de /wp-json/EmsfbShield/v1/*.',
  'Security & Spam Protection tabs' => 'Onglets Sécurité et protection anti-spam',
  'Security log export is unavailable because this server has disabled a required PHP function: %s. Ask your hosting provider to enable it.' => 'L\'exportation des journaux de sécurité n\'est pas disponible car ce serveur a désactivé une fonction PHP requise : %s. Demandez à votre fournisseur d\'hébergement de l\'activer.',
  'Security log export is unavailable because this server has disabled required PHP functions: %s. Ask your hosting provider to enable them.' => 'L\'exportation des journaux de sécurité n\'est pas disponible car ce serveur a désactivé les fonctions PHP requises : %s. Demandez à votre fournisseur d\'hébergement de les activer.',
