  'In Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.' => 'Dans Form Builder, ouvrez les paramètres du formulaire et activez « Remplir automatiquement ». Choisissez votre ensemble de données, puis mappez les éléments aux champs de l\'ensemble de données comme conditions de recherche.',
  'Enable Auto-Populate' => 'Activer le remplissage automatique',
