  'Sync Form Responses to Google Sheets' => 'Synchroniser les réponses du formulaire avec Google Sheets',
  'Automatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.' => 'Envoyez automatiquement les soumissions de formulaires à vos feuilles de calcul Google. Connectez un ou plusieurs comptes de service, associez une feuille à chaque formulaire et laissez les données circuler en temps réel : aucun webhook ou connexion au navigateur n\'est requis.',
