  'Connect one or more Google service accounts — no browser login required' => 'Connectez un ou plusieurs comptes de service Google – aucune connexion au navigateur requise',
  'Your server is missing the PHP OpenSSL extension.' => 'Votre serveur ne dispose pas de l\'extension PHP OpenSSL.',
  'Google Sheet sync cannot work until it is enabled. Please ask your host to enable the %s PHP extension, then reload this page.' => 'La synchronisation de Google Sheet ne peut pas fonctionner tant qu\'elle n\'est pas activée. Veuillez demander à votre hébergeur d\'activer l\'extension PHP %s, puis recharger cette page.',
  'Copy this email' => 'Copiez cet e-mail',
  'Copy email' => 'Copier l\'e-mail',
  'To sync an <strong>existing</strong> sheet: open it in Google Sheets &rarr; <strong>Share</strong> &rarr; paste the email above &rarr; set role to <strong>Editor</strong>. To create a <strong>new</strong> sheet, just use Form Bindings — no sharing needed.' => 'Pour synchroniser une feuille<strong></strong>existante : ouvrez-la dans Google Sheets →<strong>Partager</strong>→ collez l\'e-mail ci-dessus → définissez le rôle sur<strong>Editeur</strong>. Pour créer une nouvelle feuille<strong></strong>, utilisez simplement les liaisons de formulaire : aucun partage n\'est nécessaire.',
  'Set Default' => 'Définir par défaut',
  'Retest' => 'Retester',
  'Let’s connect Google Sheets — about 3 minutes, one time' => 'Connectons Google Sheets — environ 3 minutes, une fois',
  'Follow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.' => 'Suivez les étapes numérotées à droite pour télécharger une clé de compte de service gratuite auprès de Google, puis déposez le fichier ci-dessous. Vous ne faites cela qu\'une seule fois. Après cela, créer une feuille pour n\'importe quel formulaire se fait en quelques clics.',
  'Your Google email' => 'Votre adresse e-mail Google',
  '(recommended)' => '(recommandé)',
  'Any sheet the plugin <strong>creates</strong> is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => 'Toute feuille créée par le plug-in<strong></strong>est automatiquement partagée avec cette adresse. Elle apparaît donc dans votre propre Google Drive sous "Partagé avec moi". Sans cela, les nouvelles feuilles restent cachées dans le compte de service.',
  'Enable Google Sheet Integration' => 'Activer l\'intégration de Google Sheet',
  'Sync form submissions to your spreadsheets automatically' => 'Synchronisez automatiquement les soumissions de formulaires avec vos feuilles de calcul',
  'Drag & drop service account JSON file(s) here' => 'Faites glisser et déposez le(s) fichier(s) JSON du compte de service ici',
  'or click to browse — you can add multiple service accounts at once' => 'i cliquez pour parcourir : vous pouvez ajouter plusieurs comptes de service à la fois',
  'Connected service accounts' => 'Comptes de services connectés',
  'One-time setup (≈3 min)' => 'Configuration unique (≈3 min)',
  'Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> &rarr; Project dropdown (top-left) &rarr; New Project &rarr; name it &rarr; Create' => 'Accédez à<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ liste déroulante Projet (en haut à gauche) → Nouveau projet → nommez-le → Créer',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> <em>and</em> <strong>Google Drive API</strong>' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong><em>et</em><strong>API Google Drive</strong>',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; name it &rarr; Done' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → nommer le → Terminé',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; JSON (downloads automatically)' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → JSON (téléchargement automatique)',
  'Drag that downloaded file into the box on the left — it is tested automatically' => 'Faites glisser le fichier téléchargé dans la zone de gauche : il est testé automatiquement',
  'Add <strong>Your Google email</strong> above so created sheets land in your Drive' => 'Ajoutez<strong>Votre e-mail Google</strong>ci-dessus pour que les feuilles créées atterrissent dans votre Drive',
  'Please choose a valid .json key file.' => 'Veuillez choisir un fichier de clé .json valide.',
