  'Click <strong>“Browse My Sheets”</strong> to list spreadsheets this service account can already access, or <strong>“Create New Sheet”</strong> to make a fresh one.' => 'Cliquez sur<strong>« Parcourir mes feuilles »</strong>pour répertorier les feuilles de calcul auxquelles ce compte de service peut déjà accéder, ou sur<strong>« Créer une nouvelle feuille »</strong>pour en créer une nouvelle.',
  '<strong>No spreadsheets are accessible to this service account yet.</strong> You have two options:' => '<strong>Aucune feuille de calcul n\'est encore accessible à ce compte de service.</strong>Vous avez deux options :',
  '<strong>Easiest:</strong> click <em>“Create New Sheet”</em> above — it is made for you and shared to your email automatically.' => '<strong>Le plus simple :</strong>cliquez sur<em>"Créer une nouvelle feuille"</em>ci-dessus : elle est créée pour vous et partagée automatiquement sur votre adresse e-mail.',
  '<strong>Use an existing sheet:</strong> open it in Google Sheets &rarr; Share &rarr; paste' => '<strong>Utiliser une feuille existante :</strong>l\'ouvrir dans Google Sheets → Partager → coller',
  '&rarr; Editor, then click <em>Browse My Sheets</em> again.' => '→ Éditeur, puis cliquez à nouveau sur<em>Parcourir mes feuilles</em>.',
  'the service account email' => 'l\'e-mail du compte de service',
