  'Sheet created and shared with your email. It’s selected below — click Next to finish.' => 'Feuille créée et partagée avec votre email. Il est sélectionné ci-dessous — cliquez sur Suivant pour terminer.',
  'Sheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.' => 'Feuille créée. Astuce : ajoutez « Votre adresse e-mail Google » dans l\'onglet Connexions pour que les nouvelles feuilles vous soient automatiquement partagées.',
  'Open the new sheet' => 'Ouvrez la nouvelle feuille',
