  'Browse My Sheets' => 'Parcourir mes feuilles',
  'Create New Sheet' => 'Créer une nouvelle feuille',
  'Choose or create a spreadsheet first' => 'Choisissez ou créez d\'abord une feuille de calcul',
  'Please select a service account.' => 'Veuillez sélectionner un compte de service.',
  'Please choose or create a spreadsheet first.' => 'Veuillez d\'abord choisir ou créer une feuille de calcul.',
  'Enable Sync for this Form' => 'Activer la synchronisation pour ce formulaire',
  'Disable to pause without deleting the binding' => 'Désactiver la pause sans supprimer la liaison',
  'Reading this form’s fields…' => 'Lecture des champs de ce formulaire...',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry — <strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => 'Nous n’avons pas pu lire automatiquement les champs de ce formulaire, le mappage des colonnes n’est donc pas disponible. Ne vous inquiétez pas,<strong>chaque champ soumis sera toujours synchronisé automatiquement</strong>, chacun dans sa propre colonne, dans l\'ordre de soumission. La ligne d\'en-tête est créée et mise à jour pour vous.',
  'Drag rows (or use ▲▼) to set the <strong>column order</strong>. Rename any <strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C…) shows where each field lands.' => 'Faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre des colonnes<strong></strong>. Renommez n\'importe quel en-tête<strong></strong>. Désactivez un champ pour ignorer sa colonne. La lettre (A, B, C...) indique où se situe chaque champ.',
  'Col' => 'Col',
  'Spreadsheet header' => 'En-tête de la feuille de calcul',
  'Order / On' => 'Commander / Sur',
  'Refresh fields from form' => 'Actualiser les champs du formulaire',
  'Columns & Field Mapping' => 'Mappage des colonnes et des champs',
  'Submitted time' => 'Heure de soumission',
  'Submitted At' => 'Soumis à',
  'Column header' => 'En-tête de colonne',
  'Include this field' => 'Inclure ce champ',
  '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.' => 'La colonne %d sera écrite dans la feuille.' . chr(0) . 'Les colonnes %d seront écrites dans la feuille.',
  'Sheet Style' => 'Style de feuille',
  '(Google theme)' => '(thème Google)',
  'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.' => 'Choisissez un look pour la feuille : en-tête coloré, ligne supérieure gelée et couleurs de ligne alternées (style propre à Google Sheets). Il est appliqué automatiquement lors de la première synchronisation, ou appliquez-le maintenant.',
  'Apply style now' => 'Appliquer le style maintenant',
  'Applying…' => 'Candidature...',
  'Optional — it also applies on the first submission.' => 'Facultatif — cela s\'applique également à la première soumission.',
  'Spreadsheet:' => 'Feuille de calcul :',
  'Tab:' => 'Onglet :',
  'Columns:' => 'Colonnes :',
  '%d mapped' => '%d mappé',
  'all submitted fields (auto)' => 'tous les champs soumis (auto)',
  'Style:' => 'Style :',
  'After saving, submit the form once to create the header row and confirm the first sync.' => 'Après avoir enregistré, soumettez le formulaire une fois pour créer la ligne d\'en-tête et confirmer la première synchronisation.',
  'Save Binding' => 'Enregistrer la liaison',
  'Please choose a spreadsheet first.' => 'Veuillez d\'abord choisir une feuille de calcul.',
  'Pick a style first — “None” leaves the sheet unstyled.' => 'Choisissez d\'abord un style : "Aucun" laisse la feuille sans style.',
  'Style applied.' => 'Style appliqué.',
  'Please select a form.' => 'Veuillez sélectionner un formulaire.',
  'Please choose a spreadsheet.' => 'Veuillez choisir une feuille de calcul.',
  'Binding saved.' => 'Liaison enregistrée.',
  'Remove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.' => 'Supprimer cette liaison ? La synchronisation s\'arrête pour ce formulaire. Votre feuille Google Sheet et ses données ne sont pas supprimées.',
  'Sync removed — your Google Sheet and its data are untouched.' => 'Sync supprimée : votre feuille Google et ses données restent intactes.',
  'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Supprimer TOUTES les liaisons %d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.' . chr(0) . 'Supprimer TOUTES les liaisons %d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.',
  'All bindings removed. Your Google Sheets are untouched.' => 'Toutes les liaisons ont été supprimées. Vos feuilles Google Sheets sont intactes.',
  'Help & Setup Guide' => 'Aide et guide de configuration',
  'Everything you need to connect forms to Google Sheets' => 'Tout ce dont vous avez besoin pour connecter des formulaires à Google Sheets',
  'Step-by-Step Setup' => 'Configuration étape par étape',
  'Create or Select a Project' => 'Créer ou sélectionner un projet',
  'Open console.cloud.google.com and log in &rarr; click the Project dropdown (top-left) &rarr; New Project (or pick an existing one) &rarr; enter a name &rarr; Create' => 'Ouvrez console.cloud.google.com et connectez-vous → cliquez sur le menu déroulant Projet (en haut à gauche) → Nouveau projet (ou choisissez-en un existant) → saisissez un nom → Créer',
  'Enable both Google APIs' => 'Activer les deux API Google',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> and <strong>Google Drive API</strong> (both are required — Drive lists and creates the files)' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong>et<strong>API Google Drive</strong>(les deux sont obligatoires : Drive répertorie et crée les fichiers)',
  'Create a Service Account' => 'Créer un compte de service',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; enter a name &rarr; Done' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → saisir un nom → Terminé',
  'Create a JSON Key' => 'Créer une clé JSON',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; choose JSON (file downloads automatically)' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → choisissez JSON (téléchargement automatique des fichiers)',
  'Drop the Key File' => 'Supprimez le fichier clé',
  'Drag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge' => 'Faites glisser le fichier téléchargé dans l\'onglet Connexions : il est vérifié automatiquement et vous verrez un badge vert "Connecté"',
  'Add Your Google Email' => 'Ajoutez votre adresse e-mail Google',
  'On the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive' => 'Dans l\'onglet Connexions, remplissez "Votre e-mail Google" et enregistrez : les feuilles créées par le plugin vous sont ensuite partagées afin qu\'elles apparaissent dans votre propre Drive',
  'Bind a Form (create a sheet)' => 'Lier un formulaire (créer une feuille)',
  'Form Bindings &rarr; pick a form &rarr; <strong>Create New Sheet</strong> &rarr; Save. No manual sharing needed — this is the easiest path' => 'Liaisons de formulaire → choisir un formulaire →<strong>Créer une nouvelle feuille</strong>→ Enregistrer. Aucun partage manuel n\'est nécessaire : c\'est le chemin le plus simple',
  '…or use an existing sheet' => '...ou utiliser une feuille existante',
  'Prefer your own sheet? Open it &rarr; Share &rarr; paste the service account email (copy button on its card) &rarr; Editor &rarr; then Browse My Sheets in the wizard' => 'Vous préférez votre propre feuille ? Ouvrez-le → Partager → collez l\'e-mail du compte de service (bouton copier sur sa carte) → Éditeur → puis Parcourir mes feuilles dans l\'assistant',
  'I created a sheet — where did it go?' => 'J\'ai créé une feuille : où est-elle passée ?',
  'Service accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.' => 'Les comptes de service créent des fichiers dans leur propre Drive masqué. Ajoutez « Votre e-mail Google » dans l’onglet Connexions et le plugin vous partage automatiquement chaque nouvelle feuille – elle apparaît ensuite sous « Partagé avec moi » dans votre Google Drive. Chaque feuille comporte également un lien « Ouvrir » directement dans ce tableau de bord.',
  'Why don’t I see my existing sheet in the picker?' => 'Pourquoi ma feuille existante ne s\'affiche-t-elle pas dans le sélecteur ?',
  'It must be shared with the service account’s email first: open the sheet &rarr; Share &rarr; paste the email (use the copy button on the connection card) &rarr; set Editor &rarr; Share. Then click “Browse My Sheets” again.' => 'Il doit d\'abord être partagé avec l\'email du compte de service : ouvrir la feuille → Partager → coller l\'email (utiliser le bouton copier sur la carte de connexion) → définir l\'Editeur → Partager. Cliquez ensuite à nouveau sur « Parcourir mes feuilles ».',
  'Test result: Google API is not enabled.' => 'Résultat du test : l\'API Google n\'est pas activée.',
  'Open Google Cloud Console for the same project &rarr; APIs &amp; Services &rarr; Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Ouvrez Google Cloud Console pour le même projet → API et services → Bibliothèque, et activez À LA FOIS « API Google Sheets » et « API Google Drive ». Attendez une minute, puis retestez.',
  'Test result: Access/Permission denied' => 'Résultat du test : Accès/Autorisation refusée',
  'The service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.' => 'Le compte de service peut s\'authentifier mais ne peut pas accéder à cette feuille de calcul spécifique. Partagez à nouveau la feuille avec l\'adresse e-mail du compte de service en tant qu\'éditeur, ou créez plutôt une nouvelle feuille.',
  'OpenSSL is required.' => 'OpenSSL est requis.',
  'The server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.' => 'Le serveur ne dispose pas de l\'extension PHP OpenSSL utilisée pour signer la requête sécurisée de Google. Demandez à votre hébergeur de l\'activer : aucun paramètre de plug-in ne peut le remplacer.',
  'Can I connect more than one service account?' => 'Puis-je connecter plusieurs comptes de service ?',
  'Yes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.' => 'Oui : déposez autant de clés JSON que vous le souhaitez dans l\'onglet Connexions et choisissez celle que chaque liaison de formulaire doit utiliser.',
  'Does the connection expire?' => 'La connexion expire-t-elle ?',
  'No. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.' => 'Non. L\'intégration s\'exécute entièrement sur le serveur à l\'aide de votre clé JSON : aucune session de navigateur ni connexion ne doit expirer.',
  'Can I choose which field goes to which column?' => 'Puis-je choisir quel champ va à quelle colonne ?',
  'Yes. In the binding wizard’s <strong>Columns &amp; Fields</strong> step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Oui. À l\'étape<strong>Colonnes et champs</strong>de l\'assistant de liaison, faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre, renommez chaque en-tête de colonne et désactivez n\'importe quel champ pour l\'ignorer. Le badge A/B/C indique exactement où atterrit chaque champ.',
  'Can I style the sheet automatically?' => 'Puis-je styliser la feuille automatiquement ?',
  'Yes. The <strong>Style &amp; Save</strong> step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Oui. L\'étape<strong>Style & Save</strong>propose des thèmes Google-Sheets (en-tête coloré, ligne supérieure gelée, couleurs de ligne alternées). Choisissez-en un et il sera appliqué lors de la première synchronisation, ou cliquez sur "Appliquer le style maintenant".',
  'What if my form fields change later?' => 'Que se passe-t-il si les champs de mon formulaire changent ultérieurement ?',
  'New fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.' => 'De nouveaux champs sont ajoutés automatiquement. En mode mappé, ouvrez l\'étape Colonnes et cliquez sur « Actualiser les champs du formulaire » pour les intégrer dans le mappage ; en mode « Tous les champs du formulaire », ils apparaissent sous forme de nouvelles colonnes lors de la prochaine soumission.',
  'What if the tab doesn’t exist yet?' => 'Que se passe-t-il si l\'onglet n\'existe pas encore ?',
  'It is created automatically the first time a submission is synced.' => 'Il est créé automatiquement la première fois qu\'une soumission est synchronisée.',
  'Google Sheet Sync Logs' => 'Journaux de synchronisation Google Sheet',
  'Latest submissions sent to Google Sheets, success or failure' => 'Dernières soumissions envoyées à Google Sheets, succès ou échec',
  'Log cleared.' => 'Journal effacé.',
  'Clear Log' => 'Effacer le journal',
  'Clear all logs?' => 'Effacer tous les journaux ?',
  'No sync activity yet.' => 'Aucune activité de synchronisation pour l\'instant.',
  'Spreadsheet' => 'Feuille de calcul',
  'Synced' => 'synchronisé',
  'None (plain)' => 'Aucun (simple)',
  'Minimal' => 'Minimal',
  'Slate' => 'Ardoise',
  'Sunset' => 'Coucher de soleil',
  'Grape' => 'Raisin',
  '%s is currently unavailable.' => '%s est actuellement indisponible.',
  'disabled in php.ini: %s' => 'désactivé dans php.ini : %s',
  'not provided by PHP or its required extension: %s' => 'non fourni par PHP ou son extension requise : %s',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.' => '%1$s ne peut pas s\'exécuter car les fonctions PHP requises ne sont pas disponibles (%2$s). Demandez à votre fournisseur d\'hébergement d\'activer l\'extension PHP requise ou supprimez les fonctions répertoriées de Disabled_functions dans php.ini.',
  'This add-on is not included in Flux Forms.' => 'Ce module complémentaire n\'est pas inclus dans Flux Forms.',
  'Error: server (%s) responded with an invalid request. responded code : %s ' => 'Erreur : le serveur (%s) a répondu avec une requête non valide. code répondu : %s',
  'Your Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.' => 'Votre abonnement Easy Form Builder Pro a expiré, ce module complémentaire ne peut donc pas être téléchargé.',
  'Something went wrong, please refresh the page.' => 'Quelque chose s\'est mal passé, veuillez actualiser la page.',
  'The response attachment could not be verified. Please attach the file again.' => 'La réponse en pièce jointe n\'a pas pu être vérifiée. Veuillez joindre à nouveau le fichier.',
  'You do not have permission to update these settings.' => 'Vous n\'êtes pas autorisé à mettre à jour ces paramètres.',
  'Please enter a valid admin email address.' => 'Veuillez saisir une adresse e-mail d\'administrateur valide.',
  'You do not have permission to complete setup.' => 'Vous n\'êtes pas autorisé à terminer la configuration.',
  'Invalid email address' => 'Adresse e-mail invalide',
  'Invalid sender email' => 'E-mail de l\'expéditeur invalide',
  'The sender email address is not valid.' => 'L\'adresse e-mail de l\'expéditeur n\'est pas valide.',
  'Email tester service error' => 'Erreur du service de testeur de messagerie',
  'Could not start email test.' => 'Impossible de démarrer le test de messagerie.',
  'Invalid service response' => 'Réponse du service invalide',
  'The email tester service returned an invalid response.' => 'Le service de test de courrier électronique a renvoyé une réponse non valide.',
  'The message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.' => 'Le message n\'a jamais quitté votre site Web : WordPress a signalé une erreur lors de la tentative de l\'envoyer. C\'est le seul cas où le correctif se situe réellement du côté de WordPress ou de l\'hébergement - généralement un plugin SMTP ou une messagerie PHP désactivée par l\'hôte.',
  'WordPress could not send the test email. The message never left your website, so nothing was delivered.' => 'WordPress n\'a pas pu envoyer l\'e-mail de test. Le message n\'a jamais quitté votre site Web, donc rien n\'a été livré.',
  'Email test is waiting for delivery confirmation' => 'Le test d\'e-mail attend la confirmation de livraison',
  'WordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.' => 'WordPress a envoyé l\'e-mail de test. Flux Forms attend le résultat de la livraison avant de marquer l\'e-mail comme prêt.',
  'WordPress accepted and sent the test email. Waiting for it to arrive.' => 'WordPress a accepté et envoyé l\'e-mail de test. En attendant qu\'il arrive.',
  'The email tester service returned an invalid JSON response.' => 'Le service de test d\'e-mail a renvoyé une réponse JSON non valide.',
  'The email tester service could not start the test.' => 'Le service de test de courrier électronique n\'a pas pu démarrer le test.',
  'Invalid test hash' => 'Hash de test invalide',
  'The email test hash is not valid.' => 'Le hachage de test de l\'e-mail n\'est pas valide.',
  'Your site could not connect' => 'Votre site n\'a pas pu se connecter',
  'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.' => 'Aucune connexion n\'a pu être établie depuis votre site vers notre service de test de messagerie. Il s\'agit généralement d\'un trafic sortant bloqué par votre serveur ou son réseau (certains hôtes bloquent les connexions vers d\'autres pays) plutôt que d\'un problème avec le service. Votre fournisseur d\'hébergement peut le confirmer.',
  'Service error' => 'Erreur de service',
  'The email tester service could not return the result.' => 'Le service de test de courrier électronique n\'a pas pu renvoyer le résultat.',
  'The message never left your website. WordPress reported an error while sending, so nothing could be delivered.' => 'Le message n\'a jamais quitté votre site Web. WordPress a signalé une erreur lors de l\'envoi, rien n\'a donc pu être livré.',
  'The email was sent, but it never arrived' => 'L\'e-mail a été envoyé, mais il n\'est jamais arrivé',
  'WordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.' => 'WordPress a envoyé le message avec succès, donc votre site et ce plugin ont fait leur part. Il a été perdu, retardé ou rejeté après avoir quitté WordPress - généralement le côté destinataire l\'a traité comme du spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante.',
  'Email test failed' => 'Le test de messagerie a échoué',
  'The email server test could not verify email capability.' => 'Le test du serveur de messagerie n\'a pas pu vérifier la fonctionnalité de messagerie.',
  'Email capability verified' => 'Capacité de messagerie vérifiée',
  'Server confirmed ability to send emails.' => 'Le serveur a confirmé sa capacité à envoyer des e-mails.',
  'Your emails are being delivered to spam' => 'Vos e-mails sont envoyés dans les spams',
  'WordPress sent the test email, but delivery has not been confirmed yet.' => 'WordPress a envoyé l\'e-mail de test, mais la livraison n\'a pas encore été confirmée.',
  'Email delivery failed: %s' => 'Échec de l\'envoi de l\'e-mail : %s',
  'No file was received. Please choose a file and try again.' => 'Aucun fichier n\'a été reçu. Veuillez choisir un fichier et réessayer.',
  'The file could not be read. Please try attaching it again.' => 'Le fichier n\'a pas pu être lu. Veuillez réessayer de le joindre.',
  'Enable the Email Notification Feature' => 'Activer la fonctionnalité de notification par e-mail',
  'To receive email notifications from your forms, verify your email server by following these steps:' => 'Pour recevoir des notifications par e-mail à partir de vos formulaires, vérifiez votre serveur de messagerie en suivant ces étapes :',
  'Go to the <a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => 'Accédez au panneau Flux Forms<a href="%s" style="font-weight:600;"></a>',
  'Click Settings from the top menu' => 'Cliquez sur Paramètres dans le menu supérieur',
  'Select the Email Settings tab' => 'Sélectionnez l\'onglet Paramètres de messagerie',
  'Click "Check Email Server" and wait for the test to finish' => 'Cliquez sur "Vérifier le serveur de messagerie" et attendez la fin du test',
  'If the score is above 70 — enable the "This site can send emails" switch and save' => 'Si le score est supérieur à 70 : activez le bouton "Ce site peut envoyer des e-mails" et enregistrez',
  'Otherwise, follow the instructions shown in the test results' => 'Sinon, suivez les instructions indiquées dans les résultats du test',
  '%s notification' => 'Notification %s',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the %s feature, please ensure it is enabled.' => 'La désactivation de cette fonctionnalité peut affecter le bon fonctionnement de Flux Forms. Si vous envisagez d\'utiliser la fonctionnalité %s, assurez-vous qu\'elle est activée.',
  'Email system is working properly.' => 'Le système de messagerie fonctionne correctement.',
  'Your server is able to send emails using the default PHP mail system.' => 'Votre serveur est capable d\'envoyer des e-mails en utilisant le système de messagerie PHP par défaut.',
  'Email system is not available.' => 'Le système de messagerie n\'est pas disponible.',
  'The PHP mail() function is missing. Your server cannot send emails.' => 'La fonction PHP mail() est manquante. Votre serveur ne peut pas envoyer d\'e-mails.',
  'Email sending is blocked by server settings.' => 'L\'envoi d\'e-mails est bloqué par les paramètres du serveur.',
  'The mail() function is disabled in your server PHP configuration (php.ini).' => 'La fonction mail() est désactivée dans la configuration PHP de votre serveur (php.ini).',
  'WordPress mail function not found.' => 'Fonction de messagerie WordPress introuvable.',
  'The wp_mail() function is missing or not available. WordPress email features may be broken.' => 'La fonction wp_mail() est manquante ou non disponible. Les fonctionnalités de messagerie WordPress peuvent être interrompues.',
  'No email handler configured.' => 'Aucun gestionnaire de messagerie configuré.',
  'Your server has no SMTP host or sendmail path set. Emails may not be delivered.' => 'Votre serveur n\'a pas d\'hôte SMTP ou de chemin sendmail défini. Les e-mails risquent de ne pas être livrés.',
  'Test email could not be sent.' => 'L\'e-mail de test n\'a pas pu être envoyé.',
  'It seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.' => 'Il semble que votre site WordPress n\'ait pas pu envoyer d\'e-mail de test. Pour tester manuellement votre système de messagerie, accédez à Flux Forms > Paramètres > onglet Paramètres de messagerie et cliquez sur le bouton « Vérifier le serveur de messagerie ».',
  'Invalid email address.' => 'Adresse e-mail invalide.',
  'Please enter a valid admin email address before testing email delivery.' => 'Veuillez saisir une adresse e-mail d\'administrateur valide avant de tester la livraison des e-mails.',
  'Invalid sender email.' => 'E-mail de l\'expéditeur invalide.',
  'The sender email address is not valid. Please check your email settings.' => 'L\'adresse e-mail de l\'expéditeur n\'est pas valide. Veuillez vérifier vos paramètres de messagerie.',
  'Email tester service error.' => 'Erreur du service de testeur de messagerie.',
  'Flux Forms could not start the email delivery test. Please try again later.' => 'Flux Forms n\'a pas pu démarrer le test de livraison des e-mails. Veuillez réessayer plus tard.',
  'Invalid email tester response.' => 'Réponse du testeur d\'e-mail non valide.',
  'Invalid email test.' => 'Test d\'e-mail non valide.',
  'The email test identifier is invalid. Please start a new test.' => 'L\'identifiant du test de courrier électronique n\'est pas valide. Veuillez démarrer un nouveau test.',
  'Email tester connection error.' => 'Erreur de connexion du testeur de messagerie.',
  'Flux Forms could not connect to the email tester service.' => 'Flux Forms n\'a pas pu se connecter au service de testeur de courrier électronique.',
  'Email delivery test failed.' => 'Le test de remise des e-mails a échoué.',
  'Your emails are arriving in the spam folder.' => 'Vos e-mails arrivent dans le dossier spam.',
  'The test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.' => 'Le message de test a été livré, mais son score de délivrabilité est trop faible pour être fiable. L\'envoi via SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine résolvent ce problème.',
  'Email delivery test is pending.' => 'Le test de livraison des e-mails est en attente.',
  'Email Issue' => 'Problème de courrier électronique',
  'Flux Forms Email Warning:' => 'Avertissement par e-mail Flux Forms :',
  'Plan data is missing.' => 'Les données du plan sont manquantes.',
  'Invalid plan data format.' => 'Format de données du plan non valide.',
  'Invalid plan type.' => 'Type de forfait non valide.',
  'Please confirm this plan downgrade before continuing.' => 'Veuillez confirmer ce forfait avant de continuer.',
  'Free plan activated - no additional features.' => 'Forfait gratuit activé - aucune fonctionnalité supplémentaire.',
  'Free Plus plan activated with enhanced features.' => 'Forfait Free Plus activé avec des fonctionnalités améliorées.',
  'Pro plan activated with existing activation code.' => 'Forfait Pro activé avec le code d\'activation existant.',
  'Redirecting to Pro plan purchase page.' => 'Redirection vers la page d\'achat du forfait Pro.',
  'Plan "%s" has been successfully processed.' => 'Le plan "%s" a été traité avec succès.',
  'Addon Installation Issue' => 'Problème d\'installation du module complémentaire',
  'Technical Details' => 'Détails techniques',
  'Checked %s' => 'Vérifié %s',
  'System Ready' => 'Système prêt',
  'Checking add-on installation capabilities&hellip;' => 'Vérification des capacités d\'installation des modules complémentaires...',
  'This check runs once after plugin activation. Please refresh the page in a few moments.' => 'Cette vérification s\'exécute une fois après l\'activation du plugin. Veuillez actualiser la page dans quelques instants.',
  'Some add-ons need a PHP server change' => 'Certains modules complémentaires nécessitent un changement de serveur PHP',
  'Flux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.' => 'Flux Forms a mis en pause en toute sécurité chaque module complémentaire actif concerné, afin que le reste du plugin puisse continuer à fonctionner.',
  '(currently enabled and paused)' => '(actuellement activé et mis en pause)',
  '(not enabled)' => '(non activé)',
  'disabled in php.ini:' => 'désactivé dans php.ini :',
  'not provided by PHP or its required extension:' => 'non fourni par PHP ou son extension requise :',
  'This usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.' => 'Cela signifie généralement que l\'extension PHP nécessaire n\'est pas installée ou que la fonction est répertoriée dans Disable_functions dans php.ini. Veuillez demander à votre fournisseur d\'hébergement de l\'activer, puis actualisez cette page.',
  'If you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.' => 'Si vous voyez ce message, c\'est probablement pour l\'une des raisons suivantes : Si un plug-in de mise en cache est installé, ses paramètres devront peut-être être révisés.',
  'Please also ensure that you have a stable internet connection and try again.' => 'Veuillez également vous assurer que vous disposez d\'une connexion Internet stable et réessayer.',
  'Built with %sYT Form%s by %sWordPress form plugin by whitestudio.team%s' => 'Construit avec%sYT Form%spar%sPlugin de formulaire WordPress par whitestudio.team%s',
  'Free WordPress form plugin' => 'Plugin de formulaire WordPress gratuit',
  'Powered by %1$sYT Form%2$s . %3$sbest Form plugin for Wordpress%4$s.' => 'Propulsé par %1$sYT Form%2$s.%3$smeilleur plugin de formulaire pour Wordpress%4$s.',
  'Flux Forms WordPress Plugin' => 'Plugin WordPress Flux Forms',
  'This form requires a payment method. Please add one or change the form type.' => 'Ce formulaire nécessite un mode de paiement. Veuillez en ajouter un ou modifier le type de formulaire.',
  'Error Monitor' => 'Moniteur d\'erreurs',
  'WordPress Core' => 'WordPress Core',
  'Line' => 'Ligne',
  'No errors detected' => 'Aucune erreur détectée',
  'These errors may interfere with forms built using Flux Forms.' => 'Ces erreurs peuvent interférer avec les formulaires créés à l\'aide de Flux Forms.',
  'This panel is only visible to site administrators.' => 'Ce panneau n\'est visible que par les administrateurs du site.',
  'jQuery Dependency Issue' => 'jProblème de dépendance de requête',
  'jQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.' => 'jQuery n\'est pas correctement chargé ou disponible. Les fonctionnalités AJAX et des formulaires interactifs peuvent ne pas fonctionner correctement.',
  'WhiteStudio.team' => 'WhiteStudio.équipe',
  'EFB' => 'EFB',
  'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.' => 'Flux Forms est un plugin de création de formulaires WordPress gratuit et puissant permettant de créer des formulaires de contact, des formulaires de paiement, des enquêtes, des formulaires d\'inscription, des formulaires en plusieurs étapes, des formulaires de téléchargement de fichiers, des formulaires de signature électronique et des formulaires d\'enregistrement audio, vidéo et d\'écran, avec logique conditionnelle, notifications par e-mail, intégrations, gestion des entrées et protection anti-spam avancée.',
  'WordPress Form Builder Plugin' => 'Plugin de création de formulaires WordPress',
  'WordPress 5.0 or later; PHP 7.0 or later' => 'WordPress 5.0 ou version ultérieure ; PHP 7.0 ou version ultérieure',
  'Flux Forms Documentation' => 'Documentation Flux Forms',
  'Drag-and-Drop WordPress Form Builder' => 'Générateur de formulaires WordPress par glisser-déposer',
  'Unlimited Forms and Form Entries' => 'Formulaires et entrées de formulaire illimités',
  'Responsive and RTL-Friendly Forms' => 'Formulaires réactifs et compatibles RTL',
  'Contact and Inquiry Forms' => 'Formulaires de contact et de demande de renseignements',
  'Support and Feedback Forms with Message Tracking' => 'Formulaires d\'assistance et de commentaires avec suivi des messages',
  'Survey and Poll Forms with Visual Results' => 'Formulaires d\'enquête et de sondage avec résultats visuels',
  'Stripe and PayPal Payment Forms' => 'Formulaires de paiement Stripe et PayPal',
  'WordPress Login and Registration Forms' => 'Formulaires de connexion et d\'inscription WordPress',
  'File Upload Forms' => 'Formulaires de téléchargement de fichiers',
  'Audio Recording Forms' => 'Formulaires d\'enregistrement audio',
  'Video Recording Forms' => 'Formulaires d\'enregistrement vidéo',
  'Screen Recording Forms with Optional Microphone Audio' => 'Formulaires d\'enregistrement d\'écran avec microphone audio en option',
  'Private and Restricted-Access Forms' => 'Formulaires privés et à accès restreint',
  'Multi-Step Forms' => 'Formulaires en plusieurs étapes',
  'Smart Forms with Conditional Logic' => 'Formulaires intelligents avec logique conditionnelle',
  'Electronic Signature Forms' => 'Formulaires de signature électronique',
  'Location Picker Forms with OpenStreetMap and Leaflet' => 'Formulaires de sélection d\'emplacement avec OpenStreetMap et Leaflet',
  'Job Application Forms' => 'Formulaires de demande d\'emploi',
  'Event Registration Forms' => 'Formulaires d\'inscription à un événement',
  'Order Forms with Recurring and Subscription Billing' => 'Formulaires de commande avec facturation récurrente et par abonnement',
  'Drag-and-Drop File Upload Fields' => 'Champs de téléchargement de fichiers par glisser-déposer',
  'Audio, Video and Screen Recording Fields' => 'Champs d\'enregistrement audio, vidéo et d\'écran',
  'Electronic Signature and Location Picker Fields' => 'Signature électronique et champs de sélection d\'emplacement',
  'Country, State, Province and City Fields' => 'Champs Pays, État, Province et Ville',
  'Multiple-Select Dropdowns and Range Sliders' => 'Listes déroulantes à sélection multiple et curseurs de plage',
  'Rating Stars, 5-Point Scale, NPS and Yes-No Questions' => 'Étoiles de notation, échelle de 5 points, NPS et questions oui-non',
  'Switch and Toggle Fields' => 'Champs de commutation et de bascule',
  'Gregorian, Hijri and Jalali Date Pickers' => 'Sélecteurs de dates grégoriennes, hijri et jalali',
  'Telephone, Mobile and Color Picker Fields' => 'Champs de téléphone, mobile et sélecteur de couleurs',
