  '🎨 Flux Forms' => '🎨Formulaires de flux',
  'Add Flux Forms forms to your page' => 'Ajouter des formulaires Flux Forms à votre page',
  'Select Form:' => 'Sélectionner un formulaire :',
  'Custom Title (optional):' => 'Titre personnalisé (facultatif) :',
  'Shortcode:' => 'Code court :',
  'Run the email check' => 'Exécutez la vérification des e-mails',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Le dernier contrôle de livraison a noté %s sur 100. Vos messages quittent le site, mais la plupart des boîtes aux lettres les classeront comme spam, donc les personnes remplissant vos formulaires ne les verront pas. L\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine permettent de résoudre ce problème.',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Le dernier contrôle de livraison a révélé que vos messages quittent le site, mais les boîtes aux lettres les classent comme spam. L\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine permettent de résoudre ce problème.',
  'Your form emails are going to the spam folder' => 'Vos e-mails de formulaire vont dans le dossier spam',
  'Your form emails are sent, but they are not arriving' => 'Vos e-mails de formulaire sont envoyés, mais ils n\'arrivent pas',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'WordPress a envoyé le dernier message de test avec succès, donc votre site et ce plugin ont fait leur part : il a été perdu, retardé ou rejeté après avoir quitté WordPress. Habituellement, la boîte aux lettres de réception l\'a traité comme du spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante. L\'envoi via un service SMTP, avec des enregistrements SPF et DKIM pour votre domaine, est ce qui résout ce problème.',
  'WordPress cannot send your form emails' => 'WordPress ne peut pas envoyer les e-mails de votre formulaire',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => 'La dernière vérification n\'a même pas permis de transmettre un message à votre serveur de messagerie : WordPress a signalé une erreur lors de l\'envoi, donc rien n\'a quitté le site. Un plugin SMTP, ou demander à votre hôte si la messagerie PHP est désactivée, est par où commencer.',
  'Your form emails are not being delivered' => 'Vos e-mails de formulaire ne sont pas livrés',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => 'Le dernier chèque de livraison n\'a pas pu faire passer de message, donc rien de ce que vos formulaires envoient ne parvient à personne. Un serveur d\'hébergement envoie généralement du courrier sans signature fiable ; l\'envoi via un service SMTP est la solution standard.',
  'Once Weekly (Flux Forms)' => 'Une fois par semaine (Formulaires Flux)',
  'The weekly email delivery test completed successfully.' => 'Le test hebdomadaire de livraison des e-mails s\'est terminé avec succès.',
  'The weekly email delivery test found an email delivery problem.' => 'Le test hebdomadaire de livraison des e-mails a révélé un problème de livraison des e-mails.',
  'The main WordPress administrator email address is not valid.' => 'L\'adresse e-mail principale de l\'administrateur WordPress n\'est pas valide.',
  'Could not start the email delivery test.' => 'Impossible de démarrer le test de livraison des e-mails.',
  'WordPress sent the automated test email and is waiting for it to arrive.' => 'WordPress a envoyé l\'e-mail de test automatisé et attend qu\'il arrive.',
  'WordPress could not send the automated test email. The message never left this website.' => 'WordPress n\'a pas pu envoyer l\'e-mail de test automatisé. Le message n\'a jamais quitté ce site Web.',
  'The email delivery test timed out before confirmation was received.' => 'Le test de livraison des e-mails a expiré avant la réception de la confirmation.',
  'Weekly Flux Forms report for %s' => 'Rapport hebdomadaire Flux Forms pour %s',
  'Here is your weekly snapshot for %s.' => 'Voici votre instantané hebdomadaire pour %s.',
  'Report generated %s' => 'Rapport généré %s',
  'Detailed analysis' => 'Analyse détaillée',
  'Emails failed' => 'Échec des e-mails',
  'You can turn these reports off in Flux Forms settings.' => 'Vous pouvez désactiver ces rapports dans les paramètres de Flux Forms.',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => 'L\'e-mail de test a été envoyé, mais son score de délivrabilité n\'est que de %1$s sur 100 (inférieur à %2$s), donc les e-mails envoyés par vos formulaires sont très susceptibles d\'être rejetés ou filtrés comme spam.',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => 'Exécutez la vérification des e-mails pour être sûr que les messages envoyés par vos formulaires parviennent réellement aux personnes. Le chèque envoie un vrai message via le nouveau service de livraison WhiteStudio et rend compte de ce qui est arrivé.',
  'Read the guide to sending email through SMTP' => 'Lisez le guide sur l\'envoi d\'e-mails via SMTP',
  'Delivery has not been scored yet' => 'La livraison n\'a pas encore été notée',
  'WordPress sent your email, but it never arrived' => 'WordPress a envoyé votre e-mail, mais il n\'est jamais arrivé',
  'WordPress could not send your email' => 'WordPress n\'a pas pu envoyer votre email',
  'We could not confirm your emails are being delivered' => 'Nous n\'avons pas pu confirmer que vos e-mails ont été livrés',
  'out of 100' => 'sur 100',
  'Your email delivery is healthy' => 'La diffusion de vos e-mails est saine',
  'Your emails are likely going to spam' => 'Vos e-mails seront probablement du spam',
  'Your emails are not reaching anybody' => 'Vos e-mails ne parviennent à personne',
  'grade %s' => 'grade %s',
  'What you should do' => 'Ce que vous devez faire',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => 'Un serveur d\'hébergement envoie généralement des messages sans signature fiable, ce qui pousse les e-mails de votre formulaire dans le dossier spam ou les empêche d\'arriver. La solution standard consiste à envoyer via un service SMTP.',
  'Install an SMTP plugin and enter the details of your email service.' => 'Installez un plugin SMTP et saisissez les détails de votre service de messagerie.',
  'Add the SPF and DKIM records to your domain settings.' => 'Ajoutez les enregistrements SPF et DKIM aux paramètres de votre domaine.',
  'Run the email check again until the score is above %s.' => 'Exécutez à nouveau la vérification des e-mails jusqu\'à ce que le score soit supérieur à %s.',
  'You have %1$s forms: %2$s active and %3$s inactive.' => 'Vous avez des formulaires %1$s: %2$s actif et %3$s inactif.',
  'Renew Flux Forms Pro' => 'Renouveller Flux Forms Pro',
  'Get more from Flux Forms Pro' => 'Obtenez plus de Flux Forms Pro',
  'Renew your subscription to restore all Pro features and add-ons.' => 'Renouvelez votre abonnement pour restaurer toutes les fonctionnalités et modules complémentaires Pro.',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => 'Débloquez des modules complémentaires premium, des fonctionnalités illimitées et une assistance prioritaire pour vos formulaires.',
  'Renew Pro' => 'Renouveller Pro',
  'Email delivery is working' => 'La livraison par e-mail fonctionne',
  'The automated Flux Forms email delivery test completed successfully.' => 'Le test automatisé de livraison des e-mails Flux Forms s\'est terminé avec succès.',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => 'Vous pouvez joindre jusqu\'au fichier %1$d ici. Veuillez patienter environ %2$d minutes avant de réessayer.' . chr(0) . 'Vous pouvez joindre ici jusqu\'à %1$d fichiers. Veuillez patienter environ %2$d minutes avant de réessayer.',
  'This file is too large. The maximum size for this field is %s.' => 'Ce fichier est trop volumineux. La taille maximale de ce champ est %s.',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => 'Ce type de fichier n\'est pas accepté ici. Veuillez joindre l\'un des types de fichiers répertoriés dans ce champ.',
  'This file appears to be empty. Please choose a different file.' => 'Ce fichier semble être vide. Veuillez choisir un autre fichier.',
  'The uploaded file could not be verified. Please attach it again.' => 'Le fichier téléchargé n\'a pas pu être vérifié. Veuillez le joindre à nouveau.',
  'X-WP-Nonce header is missing' => 'L\'en-tête X-WP-Nonce est manquant',
  'Your form session has expired. Please reload the page.' => 'Votre session de formulaire a expiré. Veuillez recharger la page.',
  'Form ID:' => 'ID du formulaire :',
  'The form will be displayed on the frontend.' => 'Le formulaire sera affiché sur le frontend.',
  'This link uses an older format. For improved security, new email notifications include updated links.' => 'Ce lien utilise un format plus ancien. Pour une sécurité améliorée, les nouvelles notifications par e-mail incluent des liens mis à jour.',
  'It seems that you are the admin of this form. Please log in and try again.' => 'Il semble que vous soyez l\'administrateur de ce formulaire. Veuillez vous connecter et réessayer.',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => 'Flux Forms n\'a pas pu localiser les paramètres du formulaire. Veuillez vérifier vos paramètres ou contacter l\'assistance pour obtenir de l\'aide.',
  'Y/m/d \\a\\t g:ia' => 'Y/m/d \\a\\t g:ia',
  'Too many attempts. Please wait a few minutes and try again.' => 'Trop de tentatives. Veuillez patienter quelques minutes et réessayer.',
  'The recording upload could not be verified. Please record it again and retry.' => 'Le téléchargement de l\'enregistrement n\'a pas pu être vérifié. Veuillez l\'enregistrer à nouveau et réessayer.',
  'This recording format is not supported. Please record it again.' => 'Ce format d\'enregistrement n\'est pas pris en charge. Veuillez l\'enregistrer à nouveau.',
  'The server could not verify the recording format. Please contact the site administrator.' => 'Le serveur n\'a pas pu vérifier le format d\'enregistrement. Veuillez contacter l\'administrateur du site.',
  'The recording format could not be verified. Please record it again.' => 'Le format d\'enregistrement n\'a pas pu être vérifié. Veuillez l\'enregistrer à nouveau.',
  'The server could not verify the recording duration. Please record it again and try uploading.' => 'Le serveur n\'a pas pu vérifier la durée de l\'enregistrement. Veuillez l\'enregistrer à nouveau et essayer de le télécharger.',
  'The server could not store the recording. Please try again or contact the site administrator.' => 'Le serveur n\'a pas pu stocker l\'enregistrement. Veuillez réessayer ou contacter l\'administrateur du site.',
  'The recording request could not be verified. Please retry.' => 'La demande d\'enregistrement n\'a pas pu être vérifiée. Veuillez réessayer.',
  'The upload request could not be verified. Please try again.' => 'La demande de téléchargement n\'a pas pu être vérifiée. Veuillez réessayer.',
