  'Invalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.' => 'Sélection de paiement non valide. Veuillez revoir vos choix et réessayer. Si le problème persiste, contactez l\'administrateur du site.',
  'If your emails are not being delivered, try using an SMTP plugin. For more information, %1$s click here %2$s or contact our %3$s support team %4$s.' => 'Si vos e-mails ne sont pas livrés, essayez d\'utiliser un plugin SMTP. Pour plus d\'informations, %1$s cliquez ici %2$s ou contactez notre équipe d\'assistance %3$s%4$s.',
