  'This email was sent automatically. Please do not reply.' => 'Cet e-mail a été envoyé automatiquement. Veuillez ne pas répondre.',
  'Built with %1$sYT Form%2$s by %3$sWhiteStudio.team%4$s' => 'Construit avec %1$sYT Form%2$s par %3$sWhiteStudio.team%4$s',
