  'Congratulations! Email System Working' => 'Félicitations ! Le système de messagerie fonctionne',
  'Your server has successfully sent this test email. The email delivery system is properly configured and functioning.' => 'Votre serveur a envoyé avec succès cet e-mail de test. Le système de distribution de courrier électronique est correctement configuré et fonctionne.',
  'Email Delivery Tips' => 'Conseils pour l\'envoi d\'e-mails',
  'Form submitted successfully without tracking.' => 'Formulaire soumis avec succès sans suivi.',
