  'Or copy and paste this link:' => 'Ou copiez et collez ce lien :',
  'If you did not request this, you can safely ignore it.' => 'Si vous ne l\'avez pas demandé, vous pouvez l\'ignorer en toute sécurité.',
  'Hi' => 'Bonjour',
  'You have requested to reset your password.' => 'Vous avez demandé la réinitialisation de votre mot de passe.',
  'Click the button below to set a new password. This link will be valid for 24 hours.' => 'Cliquez sur le bouton ci-dessous pour définir un nouveau mot de passe. Ce lien sera valide pendant 24 heures.',
  'Verify Email' => 'Vérifier l\'e-mail',
  'Your account has been successfully created!' => 'Votre compte a été créé avec succès !',
  'Please verify your email address by clicking the button below. This activation link will be valid for 24 hours.' => 'Veuillez vérifier votre adresse e-mail en cliquant sur le bouton ci-dessous. Ce lien d\'activation sera valide pendant 24 heures.',
  'A new user has registered on your website.' => 'Un nouvel utilisateur s\'est enregistré sur votre site Web.',
  'The user has been sent a verification email to confirm their account.' => 'L\'utilisateur a reçu un e-mail de vérification pour confirmer son compte.',
  'This is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.' => 'Il s\'agit d\'un message d\'alerte concernant une erreur de validation SID. Ce problème peut être dû à un conflit de plug-in ou à une tentative non autorisée d\'accès au site Web.',
  'If you receive this email multiple times, it could indicate a recurring issue.' => 'Si vous recevez cet e-mail plusieurs fois, cela peut indiquer un problème récurrent.',
  'Please contact our support team for assistance.' => 'Veuillez contacter notre équipe d\'assistance pour obtenir de l\'aide.',
  'One or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.' => 'Un ou plusieurs plug-ins répertoriés ci-dessous, généralement liés à la mise en cache ou à la sécurité, peuvent être à l\'origine de ce problème. Pour le dépannage, désactivez-les temporairement et testez votre site.',
  'SID Validation Error' => 'Erreur de validation SID',
  'Please select a form to display.' => 'Veuillez sélectionner un formulaire à afficher.',
  'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.' => 'Générateur de formulaires par glisser-déposer : formulaires en plusieurs étapes, paiements Stripe, logique conditionnelle, tableau de bord, automatisations et intégration de certificats Flux. Fork basé sur Easy Form Builder (WhiteStudio, GPL).',
  'The currency of this form is not supported.' => 'La devise de ce formulaire n\'est pas prise en charge.',
  'The Stripe secret key is not configured.' => 'La clé secrète Stripe n\'est pas configurée.',
  'Could not connect to Stripe: %s' => 'Impossible de se connecter à Stripe : %s',
  'Stripe API error (HTTP %d).' => 'Erreur API Stripe (HTTP %d).',
  'Type your reply...' => 'Tapez votre réponse...',
  'height' => 'hauteur',
  'Checking email delivery...' => 'Vérification de la livraison des e-mails...',
  'A test email was sent. Waiting for delivery confirmation...' => 'Un e-mail de test a été envoyé. En attente de confirmation de livraison...',
  'Adds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Ajoute le total de vos activités de formulaire (formulaires, vues et soumissions) à l\'e-mail hebdomadaire que votre site envoie à l\'administrateur principal. Ces totaux sont lus sur votre propre site et ne sont jamais envoyés à WhiteStudio.',
  'A value is written to this field while another rule hides or disables it — hidden and disabled fields are not saved with the entry.' => 'Une valeur est écrite dans ce champ tandis qu\'une autre règle la masque ou la désactive — les champs masqués et désactivés ne sont pas enregistrés avec l\'entrée.',
  'Message...' => 'Message...',
  'hide' => 'cacher',
  'Uploading recording...' => 'Téléchargement de l\'enregistrement...',
  'Got it, don\'t show it again' => 'Compris, ne le montre plus',
  'Your text here...' => 'Votre texte ici...',
  'Waiting for the test email to arrive...' => 'En attente de l\'arrivée de l\'e-mail de test...',
  'Still checking — please wait a moment...' => 'Toujours en cours de vérification — veuillez patienter un instant...',
  'Starting email delivery test...' => 'Démarrage du test de livraison des e-mails...',
  'WordPress accepted and sent the message. Waiting for it to arrive...' => 'WordPress a accepté et envoyé le message. En attendant qu\'il arrive...',
  'turkey' => 'tdinde',
  'bug report' => 'rapport de bug',
  'kosher' => 'kasher',
  'banner' => 'bannière',
  'Installing add-ons...' => 'Installation de modules complémentaires...',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.' => 'Vos formulaires, entrées et paramètres restent intacts, toutes les fonctionnalités gratuites continuent de fonctionner et votre code d\'activation est toujours stocké – rien n\'a été supprimé.',
  'Open %1$sYT Form → Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => 'Ouvrez %1$sYT Form → Paramètres%2$s et appuyez sur %1$sEnregistrer%2$s. Cela vérifie à nouveau la licence immédiatement ; si la connexion est rétablie, Pro s\'allume dans la minute.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s — a firewall, proxy or regional block is the usual cause — then repeat step 1.' => 'Toujours en pause ? Demandez à votre fournisseur d\'hébergement d\'autoriser les connexions HTTPS sortantes vers %s(un pare-feu, un proxy ou un blocage régional est la cause habituelle), puis répétez l\'étape 1.',
  'grace period' => 'délai de grâce',
  'Your website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.' => 'Votre site Web n\'a pas pu atteindre le serveur de licences – presque toujours à cause d\'une restriction réseau, pare-feu ou DNS du côté de l\'hébergement.',
  'The licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'La réponse du serveur de licences est arrivée endommagée, généralement parce qu\'un plugin de sécurité, un proxy ou un CDN l\'a modifiée en cours de route.',
  'Updating amount...' => 'Mise à jour du montant...',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'Les clés sont définies ; Le formulaire %dutilise reCAPTCHA. Les formulaires %dutilisent reCAPTCHA.',
  'Preparing your certificate...' => 'Préparation de votre certificat...',
  'Search elements...' => 'Rechercher des éléments...',
  'Enter your test message here...' => 'Entrez votre message de test ici...',
  'Type your message here...' => 'Tapez votre message ici...',
  'Testing connection...' => 'Test de la connexion...',
  'Saving...' => 'Enregistrement...',
  'Loading...' => 'Chargement...',
  'To sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.' => 'Pour synchroniser une feuille<strong></strong>existante : ouvrez-la dans Google Sheets →<strong>Partager</strong>→ collez l\'e-mail ci-dessus → définissez le rôle sur<strong>Editeur</strong>. Pour créer une nouvelle feuille<strong></strong>, utilisez simplement les liaisons de formulaire : aucun partage n\'est nécessaire.',
  'Go to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create' => 'Accédez à<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ liste déroulante Projet (en haut à gauche) → Nouveau projet → nommez-le → Créer',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong><em>et</em><strong>API Google Drive</strong>',
  'APIs & Services → Credentials → Create Credentials → Service Account → name it → Done' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → nommer le → Terminé',
  'Open the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → JSON (téléchargement automatique)',
  'Connecting service account...' => 'Connexion du compte de service...',
  'tab' => 'tab',
  'Loading your spreadsheets...' => 'Chargement de vos feuilles de calcul...',
  '<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste' => '<strong>Utiliser une feuille existante :</strong>l\'ouvrir dans Google Sheets → Partager → coller',
  '→ Editor, then click<em>Browse My Sheets</em>again.' => '→ Éditeur, puis cliquez à nouveau sur<em>Parcourir mes feuilles</em>.',
  'Creating...' => 'Création...',
  'Creating spreadsheet...' => 'Création d\'une feuille de calcul...',
  'Loading worksheet tabs...' => 'Chargement des onglets de la feuille de calcul...',
  'Reading this form’s fields...' => 'Lecture des champs de ce formulaire...',
  'Drag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.' => 'Faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre des colonnes<strong></strong>. Renommez n\'importe quel en-tête<strong></strong>. Désactivez un champ pour ignorer sa colonne. La lettre (A, B, C...) indique où se situe chaque champ.',
  'Applying...' => 'Candidature...',
  'Open console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create' => 'Ouvrez console.cloud.google.com et connectez-vous → cliquez sur le menu déroulant Projet (en haut à gauche) → Nouveau projet (ou choisissez-en un existant) → saisissez un nom → Créer',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)' => 'API et services → Bibliothèque → activer<strong>API Google Sheets</strong>et<strong>API Google Drive</strong>(les deux sont obligatoires : Drive répertorie et crée les fichiers)',
  'APIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done' => 'API et services → Identifiants → Créer des informations d\'identification → Compte de service → saisir un nom → Terminé',
  'Open the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)' => 'Ouvrez le compte de service → onglet Clés → Ajouter une clé → Créer une nouvelle clé → choisissez JSON (téléchargement automatique des fichiers)',
  'Form Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path' => 'Liaisons de formulaire → choisir un formulaire →<strong>Créer une nouvelle feuille</strong>→ Enregistrer. Aucun partage manuel n\'est nécessaire : c\'est le chemin le plus simple',
  '...or use an existing sheet' => '...ou utiliser une feuille existante',
  'Prefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard' => 'Vous préférez votre propre feuille ? Ouvrez-le → Partager → collez l\'e-mail du compte de service (bouton copier sur sa carte) → Éditeur → puis Parcourir mes feuilles dans l\'assistant',
  'It must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.' => 'Il doit d\'abord être partagé avec l\'email du compte de service : ouvrir la feuille → Partager → coller l\'email (utiliser le bouton copier sur la carte de connexion) → définir l\'Editeur → Partager. Cliquez ensuite à nouveau sur « Parcourir mes feuilles ».',
  'Open Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Ouvrez Google Cloud Console pour le même projet → API et services → Bibliothèque, et activez À LA FOIS « API Google Sheets » et « API Google Drive ». Attendez une minute, puis retestez.',
  'Yes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Oui. À l\'étape<strong>Colonnes et champs</strong>de l\'assistant de liaison, faites glisser les lignes (ou utilisez ▲▼) pour définir l\'ordre, renommez chaque en-tête de colonne et désactivez n\'importe quel champ pour l\'ignorer. Le badge A/B/C indique exactement où atterrit chaque champ.',
  'Yes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Oui. L\'étape<strong>Style & Save</strong>propose des thèmes Google-Sheets (en-tête coloré, ligne supérieure gelée, couleurs de ligne alternées). Choisissez-en un et il sera appliqué lors de la première synchronisation, ou cliquez sur "Appliquer le style maintenant".',
  'synchronized' => 'synchronisé',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.' => '%1$s ne peut pas s\'exécuter car les fonctions PHP requises ne sont pas disponibles (%2$s). Demandez à votre fournisseur d\'hébergement d\'activer l\'extension PHP requise ou supprimez les fonctions répertoriées de Disabled_functions dans php.ini.',
  'Checking add-on installation capabilities...' => 'Vérification des capacités d\'installation des modules complémentaires...',
  'Powered by %1$sYT Form%2$s. %3$sbest Form plugin for Wordpress%4$s.' => 'Propulsé par %1$sYT Form%2$s.%3$smeilleur plugin de formulaire pour Wordpress%4$s.',
  'Loading forms...' => 'Chargement des formulaires...',
  'Drag-and-drop form builder: multi-step forms, Stripe payments, conditional logic, dashboard, automations and Flux Certificates integration. Fork based on Easy Form Builder (WhiteStudio, GPL).' => 'Générateur de formulaires par glisser-déposer : formulaires en plusieurs étapes, paiements Stripe, logique conditionnelle, tableau de bord, automatisations et intégration de certificats Flux. Fork basé sur Easy Form Builder (WhiteStudio, GPL).',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' . chr(0) . 'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'Les clés sont définies ; Le formulaire %dutilise reCAPTCHA. Les formulaires %dutilisent reCAPTCHA.' . chr(0) . 'Les clés sont définies ; Le formulaire %dutilise reCAPTCHA. Les formulaires %dutilisent reCAPTCHA.',
  'field\\x00fields' => 'field' . chr(0) . 'fields',
  'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".' => 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : le formulaire de paiement %daffiche "Le paiement en ligne n\'est pas disponible".' . chr(0) . 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : les formulaires de paiement %dindiquent "Le paiement en ligne n\'est pas disponible".',
  'Not active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.' => 'Non actif, mais l\'automatisation active%dcrée ou envoie des certificats ; ça va échouer.' . chr(0) . 'Non actif, mais les automatisations actives%dcréent ou envoient des certificats ; ils échoueront.',
  '%dautomation is on.\\x00%dautomations are on.' => ' L\'automatisation %dest activée.' . chr(0) . ' Les automatisations %dsont activées.',
  '%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.' => ' L\'exécution de %da échoué au cours des 7 derniers jours ; voir le journal d\'exécution.' . chr(0) . ' Les exécutions %dont échoué au cours des 7 derniers jours ; voir le journal d\'exécution.',
  '%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' => ' Le formulaire %dcontient reCAPTCHA mais la clé du site ou la clé secrète est manquante ; le formulaire n\'est pas affiché.' . chr(0) . ' Les formulaires %dont reCAPTCHA activé mais la clé du site ou la clé secrète est manquante ; ils ne sont pas affichés.',
  'Form\\x00Forms' => 'Formulaire' . chr(0) . 'Formulaires',
  '%dservice account connected\\x00%dservice accounts connected' => 'Compte de service %dconnecté' . chr(0) . ' Comptes de service %dconnectés',
  '%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.' => 'La colonne %dsera écrite dans la feuille.' . chr(0) . ' Les colonnes %dseront écrites dans la feuille.',
  'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.' . chr(0) . 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.',
  'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.' => 'Vous pouvez joindre jusqu\'au fichier%1$dici. Veuillez patienter environ%2$dminutes avant de réessayer.' . chr(0) . 'Vous pouvez joindre jusqu\'à%1$ddes fichiers ici. Veuillez patienter environ%2$dminutes avant de réessayer.',
  'field\\x00fields' . chr(0) . 'field\\x00fields' => 'field' . chr(0) . 'fields',
  'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".' . chr(0) . 'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".' => 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : le formulaire de paiement %daffiche "Le paiement en ligne n\'est pas disponible".' . chr(0) . 'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : les formulaires de paiement %dindiquent "Le paiement en ligne n\'est pas disponible".',
  'Not active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.' . chr(0) . 'Not active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.' => 'Non actif, mais l\'automatisation active%dcrée ou envoie des certificats ; ça va échouer.' . chr(0) . 'Non actif, mais les automatisations actives%dcréent ou envoient des certificats ; ils échoueront.',
  '%dautomation is on.\\x00%dautomations are on.' . chr(0) . '%dautomation is on.\\x00%dautomations are on.' => ' L\'automatisation %dest activée.' . chr(0) . ' Les automatisations %dsont activées.',
  '%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.' . chr(0) . '%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.' => ' L\'exécution de %da échoué au cours des 7 derniers jours ; voir le journal d\'exécution.' . chr(0) . ' Les exécutions %dont échoué au cours des 7 derniers jours ; voir le journal d\'exécution.',
  '%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' . chr(0) . '%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.' => ' Le formulaire %dcontient reCAPTCHA mais la clé du site ou la clé secrète est manquante ; le formulaire n\'est pas affiché.' . chr(0) . ' Les formulaires %dont reCAPTCHA activé mais la clé du site ou la clé secrète est manquante ; ils ne sont pas affichés.',
  'Form\\x00Forms' . chr(0) . 'Form\\x00Forms' => 'Formulaire' . chr(0) . 'Formulaires',
  '%dservice account connected\\x00%dservice accounts connected' . chr(0) . '%dservice account connected\\x00%dservice accounts connected' => 'Compte de service %dconnecté' . chr(0) . ' Comptes de service %dconnectés',
  '%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.' . chr(0) . '%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.' => 'La colonne %dsera écrite dans la feuille.' . chr(0) . ' Les colonnes %dseront écrites dans la feuille.',
  'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.' . chr(0) . 'Supprimer TOUTES les liaisons%d? La synchronisation s\'arrête pour chaque formulaire. Vos feuilles Google Sheets ne sont pas supprimées.',
  'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.' . chr(0) . 'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.' => 'Vous pouvez joindre jusqu\'au fichier%1$dici. Veuillez patienter environ%2$dminutes avant de réessayer.' . chr(0) . 'Vous pouvez joindre jusqu\'à%1$ddes fichiers ici. Veuillez patienter environ%2$dminutes avant de réessayer.',

